/** static void FindLinkBattleMaster(u8 numPlayers, u8 multiPlayerId) */
export function FindLinkBattleMaster(numPlayers: any, multiPlayerId: any): any {
  let found: any = 0;

       
      if (gBlockRecvBuffer[0][0] == _0x100)
      {
          if (multiPlayerId == 0)
              gBattleTypeFlags |= BATTLE_TYPE_IS_MASTER | BATTLE_TYPE_TRAINER;
          else
              gBattleTypeFlags |= BATTLE_TYPE_TRAINER;
          found++;
      }

      if (found == 0)
      {
           
          let i: any = null;

          for (i = 0; i < numPlayers; i++)
          {
              if (gBlockRecvBuffer[0][0] != gBlockRecvBuffer[i][0])
                  break;
          }

          if (i == numPlayers)
          {
              if (multiPlayerId == 0)
                  gBattleTypeFlags |= BATTLE_TYPE_IS_MASTER | BATTLE_TYPE_TRAINER;
              else
                  gBattleTypeFlags |= BATTLE_TYPE_TRAINER;
              found++;
          }

          if (found == 0)
          {
               
              for (i = 0; i < numPlayers; i++)
              {
                  if (gBlockRecvBuffer[i][0] == _0x300 && i != multiPlayerId)
                  {
                      if (i < multiPlayerId)
                          break;
                  }
                  if (gBlockRecvBuffer[i][0] > _0x300 && i != multiPlayerId)
                      break;
              }

              if (i == numPlayers)
                  gBattleTypeFlags |= BATTLE_TYPE_IS_MASTER | BATTLE_TYPE_TRAINER;
              else
                  gBattleTypeFlags |= BATTLE_TYPE_TRAINER;
          }
      }
}

/** static void CB2_HandleStartBattle(void) */
export function CB2_HandleStartBattle(): any {
  let playerMultiplayerId: any = null;
      let enemyMultiplayerId: any = null;

      RunTasks();
      AnimateSprites();
      BuildOamBuffer();

      playerMultiplayerId = GetMultiplayerId();
      gBattleScripting.multiplayerId = playerMultiplayerId;
      enemyMultiplayerId = playerMultiplayerId ^ BIT_SIDE;

      switch (gBattleCommunication[MULTIUSE_STATE])
      {
      case 0:
          if (!IsDma3ManagerBusyWithBgCopy())
          {
              ShowBg(0);
              ShowBg(1);
              ShowBg(2);
              ShowBg(3);
              FillAroundBattleWindows();
              gBattleCommunication[MULTIUSE_STATE] = 1;
          }
          if (gWirelessCommType)
              LoadWirelessStatusIndicatorSpriteGfx();
          break;
      case 1:
          if (gBattleTypeFlags & BATTLE_TYPE_LINK)
          {
              if (gReceivedRemoteLinkPlayers)
              {
                  if (IsLinkTaskFinished())
                  {
                       
                      MEM_WRITE((gBattleStruct.multiBuffer.linkBattlerHeader.versionSignatureLo), 0);
                      MEM_WRITE((gBattleStruct.multiBuffer.linkBattlerHeader.versionSignatureHi), 3);
                      BufferPartyVsScreenHealth_AtStart();
                      SetPlayerBerryDataInBattleStruct();

                      if (gTrainerBattleOpponent_A == TRAINER_UNION_ROOM)
                      {
                          gLinkPlayers[0].id = 0;
                          gLinkPlayers[1].id = 1;
                      }

                      SendBlock(BitmaskAllOtherLinkPlayers(),gBattleStruct.multiBuffer.linkBattlerHeader, sizeof(gBattleStruct.multiBuffer.linkBattlerHeader));
                      gBattleCommunication[MULTIUSE_STATE] = 2;
                  }
                  if (gWirelessCommType)
                      CreateWirelessStatusIndicatorSprite(0, 0);
              }
          }
          else
          {
              if (!(gBattleTypeFlags & BATTLE_TYPE_RECORDED))
                  gBattleTypeFlags |= BATTLE_TYPE_IS_MASTER;
              gBattleCommunication[MULTIUSE_STATE] = 15;
              SetAllPlayersBerryData();
          }
          break;
      case 2:
          if ((GetBlockReceivedStatus() & 3) == 3)
          {
              let taskId: any = null;

              ResetBlockReceivedFlags();
              FindLinkBattleMaster(2, playerMultiplayerId);
              SetAllPlayersBerryData();
              taskId = CreateTask(InitLinkBattleVsScreen, 0);
              gTasks[taskId].data[1] = 0x10E;
              gTasks[taskId].data[2] = 0x5A;
              gTasks[taskId].data[5] = 0;
              gTasks[taskId].data[3] = gBattleStruct.multiBuffer.linkBattlerHeader.vsScreenHealthFlagsLo | (gBattleStruct.multiBuffer.linkBattlerHeader.vsScreenHealthFlagsHi << 8);
              gTasks[taskId].data[4] = gBlockRecvBuffer[enemyMultiplayerId][1];
              RecordedBattle_SetFrontierPassFlagFromHword(gBlockRecvBuffer[playerMultiplayerId][1]);
              RecordedBattle_SetFrontierPassFlagFromHword(gBlockRecvBuffer[enemyMultiplayerId][1]);
              SetDeoxysStats();
              gBattleCommunication[MULTIUSE_STATE]++;
          }
          break;
      case 3:
           
          if (IsLinkTaskFinished())
          {
               
              SendBlock(BitmaskAllOtherLinkPlayers(), gPlayerParty, 0 * 2);
              gBattleCommunication[MULTIUSE_STATE]++;
          }
          break;
      case 4:
          if ((GetBlockReceivedStatus() & 3) == 3)
          {
               
              ResetBlockReceivedFlags();
              memcpy(gEnemyParty, gBlockRecvBuffer[enemyMultiplayerId], 0 * 2);
              gBattleCommunication[MULTIUSE_STATE]++;
          }
          break;
      case 7:
          if (IsLinkTaskFinished())
          {
               
              SendBlock(BitmaskAllOtherLinkPlayers(),gPlayerParty[2], 0 * 2);
              gBattleCommunication[MULTIUSE_STATE]++;
          }
          break;
      case 8:
          if ((GetBlockReceivedStatus() & 3) == 3)
          {
               
              ResetBlockReceivedFlags();
              memcpy(gEnemyParty[2], gBlockRecvBuffer[enemyMultiplayerId], 0 * 2);
              gBattleCommunication[MULTIUSE_STATE]++;
          }
          break;
      case 11:
          if (IsLinkTaskFinished())
          {
               
              SendBlock(BitmaskAllOtherLinkPlayers(),gPlayerParty[4], 0 * 2);
              gBattleCommunication[MULTIUSE_STATE]++;
          }
          break;
      case 12:
          if ((GetBlockReceivedStatus() & 3) == 3)
          {
               
              ResetBlockReceivedFlags();
              memcpy(gEnemyParty[4], gBlockRecvBuffer[enemyMultiplayerId], 0 * 2);

              TryCorrectShedinjaLanguage(gEnemyParty[0]);
              TryCorrectShedinjaLanguage(gEnemyParty[1]);
              TryCorrectShedinjaLanguage(gEnemyParty[2]);
              TryCorrectShedinjaLanguage(gEnemyParty[3]);
              TryCorrectShedinjaLanguage(gEnemyParty[4]);
              TryCorrectShedinjaLanguage(gEnemyParty[5]);
              gBattleCommunication[MULTIUSE_STATE]++;
          }
          break;
      case 15:
          InitBattleControllers();
          RecordedBattle_SetTrainerInfo();
          gBattleCommunication[SPRITES_INIT_STATE1] = 0;
          gBattleCommunication[SPRITES_INIT_STATE2] = 0;
          if (gBattleTypeFlags & BATTLE_TYPE_LINK)
          {
               
               
               
              let i: any = null;
              for (i = 0; i < 2 && (gLinkPlayers[i].version & 0xFF) == VERSION_EMERALD; i++);

              if (i == 2)
                  gBattleCommunication[MULTIUSE_STATE] = 16;
              else
                  gBattleCommunication[MULTIUSE_STATE] = 18;
          }
          else
          {
              gBattleCommunication[MULTIUSE_STATE] = 18;
          }
          break;
      case 16:
           
          if (IsLinkTaskFinished())
          {
              SendBlock(BitmaskAllOtherLinkPlayers(),gRecordedBattleRngSeed, 0);
              gBattleCommunication[MULTIUSE_STATE]++;
          }
          break;
      case 17:
           
          if ((GetBlockReceivedStatus() & 3) == 3)
          {
              ResetBlockReceivedFlags();
              if (!(gBattleTypeFlags & BATTLE_TYPE_IS_MASTER))
                  memcpy(gRecordedBattleRngSeed, gBlockRecvBuffer[enemyMultiplayerId], 0);
              gBattleCommunication[MULTIUSE_STATE]++;
          }
          break;
      case 18:
           
          if (BattleInitAllSprites(gBattleCommunication[SPRITES_INIT_STATE1],gBattleCommunication[SPRITES_INIT_STATE2]))
          {
              gPreBattleCallback1 = gMain.callback1;
              gMain.callback1 = BattleMainCB1;
              SetMainCallback2(BattleMainCB2);
              if (gBattleTypeFlags & BATTLE_TYPE_LINK)
                  gBattleTypeFlags |= BATTLE_TYPE_LINK_IN_BATTLE;
          }
          break;
       
      case 5:
      case 9:
      case 13:
          gBattleCommunication[MULTIUSE_STATE]++;
          gBattleCommunication[1] = 1;
      case 6:
      case 10:
      case 14:
          if (--gBattleCommunication[1] == 0)
              gBattleCommunication[MULTIUSE_STATE]++;
          break;
      }
}

/** static void CB2_HandleStartMultiPartnerBattle(void) */
export function CB2_HandleStartMultiPartnerBattle(): any {
  let playerMultiplayerId: any = null;
      let partnerMultiplayerId: any = null;

      RunTasks();
      AnimateSprites();
      BuildOamBuffer();

      playerMultiplayerId = GetMultiplayerId();
      gBattleScripting.multiplayerId = playerMultiplayerId;
      partnerMultiplayerId = playerMultiplayerId ^ BIT_SIDE;

      switch (gBattleCommunication[MULTIUSE_STATE])
      {
      case 0:
          if (!IsDma3ManagerBusyWithBgCopy())
          {
              ShowBg(0);
              ShowBg(1);
              ShowBg(2);
              ShowBg(3);
              FillAroundBattleWindows();
              gBattleCommunication[MULTIUSE_STATE] = 1;
          }
          if (gWirelessCommType)
              LoadWirelessStatusIndicatorSpriteGfx();
           
      case 1:
          if (gBattleTypeFlags & BATTLE_TYPE_LINK)
          {
              if (gReceivedRemoteLinkPlayers)
              {
                  let language: any = null;

                  gLinkPlayers[0].id = 0;
                  gLinkPlayers[1].id = 2;
                  gLinkPlayers[2].id = 1;
                  gLinkPlayers[3].id = 3;
                  GetFrontierTrainerName(gLinkPlayers[2].name, gTrainerBattleOpponent_A);
                  GetFrontierTrainerName(gLinkPlayers[3].name, gTrainerBattleOpponent_B);
                  GetBattleTowerTrainerLanguage(language, gTrainerBattleOpponent_A);
                  gLinkPlayers[2].language = language;
                  GetBattleTowerTrainerLanguage(language, gTrainerBattleOpponent_B);
                  gLinkPlayers[3].language = language;

                  if (IsLinkTaskFinished())
                  {
                       
                      MEM_WRITE((gBattleStruct.multiBuffer.linkBattlerHeader.versionSignatureLo), 0);
                      MEM_WRITE((gBattleStruct.multiBuffer.linkBattlerHeader.versionSignatureHi), 3);
                      BufferPartyVsScreenHealth_AtStart();
                      SetPlayerBerryDataInBattleStruct();
                      SendBlock(BitmaskAllOtherLinkPlayers(),gBattleStruct.multiBuffer.linkBattlerHeader, sizeof(gBattleStruct.multiBuffer.linkBattlerHeader));
                      gBattleCommunication[MULTIUSE_STATE] = 2;
                  }

                  if (gWirelessCommType)
                      CreateWirelessStatusIndicatorSprite(0, 0);
              }
          }
          else
          {
              if (!(gBattleTypeFlags & BATTLE_TYPE_RECORDED))
                  gBattleTypeFlags |= BATTLE_TYPE_IS_MASTER;
              gBattleCommunication[MULTIUSE_STATE] = 13;
              SetAllPlayersBerryData();
          }
          break;
      case 2:
          if ((GetBlockReceivedStatus() & 3) == 3)
          {
              let taskId: any = null;

              ResetBlockReceivedFlags();
              FindLinkBattleMaster(2, playerMultiplayerId);
              SetAllPlayersBerryData();
              taskId = CreateTask(InitLinkBattleVsScreen, 0);
              gTasks[taskId].data[1] = 0x10E;
              gTasks[taskId].data[2] = 0x5A;
              gTasks[taskId].data[5] = 0;
              gTasks[taskId].data[3] = _0x145;
              gTasks[taskId].data[4] = _0x145;
              gBattleCommunication[MULTIUSE_STATE]++;
          }
          break;
      case 3:
           
          if (IsLinkTaskFinished())
          {
               
              SendBlock(BitmaskAllOtherLinkPlayers(), gPlayerParty, 0 * 2);
              gBattleCommunication[MULTIUSE_STATE]++;
          }
          break;
      case 4:
          if ((GetBlockReceivedStatus() & 3) == 3)
          {
               
              ResetBlockReceivedFlags();
              if (gLinkPlayers[playerMultiplayerId].id != 0)
              {
                  memcpy(gPlayerParty, gBlockRecvBuffer[partnerMultiplayerId], 0 * 2);
                  memcpy(gPlayerParty[MULTI_PARTY_SIZE], gBlockRecvBuffer[playerMultiplayerId], 0 * 2);
              }
              else
              {
                  memcpy(gPlayerParty, gBlockRecvBuffer[playerMultiplayerId], 0 * 2);
                  memcpy(gPlayerParty[MULTI_PARTY_SIZE], gBlockRecvBuffer[partnerMultiplayerId], 0 * 2);
              }
              gBattleCommunication[MULTIUSE_STATE]++;
          }
          break;
      case 5:
          if (IsLinkTaskFinished())
          {
               
              SendBlock(BitmaskAllOtherLinkPlayers(),gPlayerParty[2], 0);
              gBattleCommunication[MULTIUSE_STATE]++;
          }
          break;
      case 6:
          if ((GetBlockReceivedStatus() & 3) == 3)
          {
               
              ResetBlockReceivedFlags();
              if (gLinkPlayers[playerMultiplayerId].id != 0)
              {
                  memcpy(gPlayerParty[2], gBlockRecvBuffer[partnerMultiplayerId], 0);
                  memcpy(gPlayerParty[2 + MULTI_PARTY_SIZE], gBlockRecvBuffer[playerMultiplayerId], 0);
              }
              else
              {
                  memcpy(gPlayerParty[2], gBlockRecvBuffer[playerMultiplayerId], 0);
                  memcpy(gPlayerParty[2 + MULTI_PARTY_SIZE], gBlockRecvBuffer[partnerMultiplayerId], 0);
              }
              gBattleCommunication[MULTIUSE_STATE]++;
          }
          break;
      case 7:
          if (IsLinkTaskFinished())
          {
               
              SendBlock(BitmaskAllOtherLinkPlayers(), gEnemyParty, 0 * 2);
              gBattleCommunication[MULTIUSE_STATE]++;
          }
          break;
      case 8:
          if ((GetBlockReceivedStatus() & 3) == 3)
          {
               
              ResetBlockReceivedFlags();
              if (GetMultiplayerId() != 0)
                  memcpy(gEnemyParty, gBlockRecvBuffer[0], 0 * 2);
              gBattleCommunication[MULTIUSE_STATE]++;
          }
          break;
      case 9:
          if (IsLinkTaskFinished())
          {
               
              SendBlock(BitmaskAllOtherLinkPlayers(),gEnemyParty[2], 0 * 2);
              gBattleCommunication[MULTIUSE_STATE]++;
          }
          break;
      case 10:
          if ((GetBlockReceivedStatus() & 3) == 3)
          {
               
              ResetBlockReceivedFlags();
              if (GetMultiplayerId() != 0)
                  memcpy(gEnemyParty[2], gBlockRecvBuffer[0], 0 * 2);
              gBattleCommunication[MULTIUSE_STATE]++;
          }
          break;
      case 11:
          if (IsLinkTaskFinished())
          {
               
              SendBlock(BitmaskAllOtherLinkPlayers(),gEnemyParty[4], 0 * 2);
              gBattleCommunication[MULTIUSE_STATE]++;
          }
          break;
      case 12:
          if ((GetBlockReceivedStatus() & 3) == 3)
          {
               
              ResetBlockReceivedFlags();
              if (GetMultiplayerId() != 0)
                  memcpy(gEnemyParty[4], gBlockRecvBuffer[0], 0 * 2);

              TryCorrectShedinjaLanguage(gPlayerParty[0]);
              TryCorrectShedinjaLanguage(gPlayerParty[1]);
              TryCorrectShedinjaLanguage(gPlayerParty[2]);
              TryCorrectShedinjaLanguage(gPlayerParty[3]);
              TryCorrectShedinjaLanguage(gPlayerParty[4]);
              TryCorrectShedinjaLanguage(gPlayerParty[5]);
              TryCorrectShedinjaLanguage(gEnemyParty[0]);
              TryCorrectShedinjaLanguage(gEnemyParty[1]);
              TryCorrectShedinjaLanguage(gEnemyParty[2]);
              TryCorrectShedinjaLanguage(gEnemyParty[3]);
              TryCorrectShedinjaLanguage(gEnemyParty[4]);
              TryCorrectShedinjaLanguage(gEnemyParty[5]);
              gBattleCommunication[MULTIUSE_STATE]++;
          }
          break;
      case 13:
          InitBattleControllers();
          RecordedBattle_SetTrainerInfo();
          gBattleCommunication[SPRITES_INIT_STATE1] = 0;
          gBattleCommunication[SPRITES_INIT_STATE2] = 0;
          if (gBattleTypeFlags & BATTLE_TYPE_LINK)
              gBattleCommunication[MULTIUSE_STATE] = 14;
          else
              gBattleCommunication[MULTIUSE_STATE] = 16;
          break;
      case 14:
           
          if (IsLinkTaskFinished())
          {
              SendBlock(BitmaskAllOtherLinkPlayers(),gRecordedBattleRngSeed, 0);
              gBattleCommunication[MULTIUSE_STATE]++;
          }
          break;
      case 15:
           
          if ((GetBlockReceivedStatus() & 3) == 3)
          {
              ResetBlockReceivedFlags();
              if (!(gBattleTypeFlags & BATTLE_TYPE_IS_MASTER))
                  memcpy(gRecordedBattleRngSeed, gBlockRecvBuffer[partnerMultiplayerId], 0);
              gBattleCommunication[MULTIUSE_STATE]++;
          }
          break;
      case 16:
           
          if (BattleInitAllSprites(gBattleCommunication[SPRITES_INIT_STATE1],gBattleCommunication[SPRITES_INIT_STATE2]))
          {
              TrySetLinkBattleTowerEnemyPartyLevel();
              gPreBattleCallback1 = gMain.callback1;
              gMain.callback1 = BattleMainCB1;
              SetMainCallback2(BattleMainCB2);
              if (gBattleTypeFlags & BATTLE_TYPE_LINK)
                  gBattleTypeFlags |= BATTLE_TYPE_LINK_IN_BATTLE;
          }
          break;
      }
}

/** static void SetMultiPartnerMenuParty(u8 offset) */
export function SetMultiPartnerMenuParty(offset: any): any {
  let i: any = null;

      for (i = 0; i < MULTI_PARTY_SIZE; i++)
      {
          gMultiPartnerParty[i].species     = GetMonData(gPlayerParty[offset + i], MON_DATA_SPECIES);
          gMultiPartnerParty[i].heldItem    = GetMonData(gPlayerParty[offset + i], MON_DATA_HELD_ITEM);
          GetMonData(gPlayerParty[offset + i], MON_DATA_NICKNAME, gMultiPartnerParty[i].nickname);
          gMultiPartnerParty[i].level       = GetMonData(gPlayerParty[offset + i], MON_DATA_LEVEL);
          gMultiPartnerParty[i].hp          = GetMonData(gPlayerParty[offset + i], MON_DATA_HP);
          gMultiPartnerParty[i].maxhp       = GetMonData(gPlayerParty[offset + i], MON_DATA_MAX_HP);
          gMultiPartnerParty[i].status      = GetMonData(gPlayerParty[offset + i], MON_DATA_STATUS);
          gMultiPartnerParty[i].personality = GetMonData(gPlayerParty[offset + i], MON_DATA_PERSONALITY);
          gMultiPartnerParty[i].gender      = GetMonGender(gPlayerParty[offset + i]);
          StripExtCtrlCodes(gMultiPartnerParty[i].nickname);
          if (GetMonData(gPlayerParty[offset + i], MON_DATA_LANGUAGE) != LANGUAGE_JAPANESE)
              PadNameString(gMultiPartnerParty[i].nickname, CHAR_SPACE);
      }
      memcpy(sMultiPartnerPartyBuffer, gMultiPartnerParty, 0);
}

/** static void CB2_PreInitMultiBattle(void) */
export function CB2_PreInitMultiBattle(): any {
  let i: any = null;
      let playerMultiplierId: any = null;
      let numPlayers: any = MAX_BATTLERS_COUNT;
      let blockMask: any = 0xF;
      let savedBattleTypeFlags: any = null;
      let savedCallback: any = null;

      if (gBattleTypeFlags & BATTLE_TYPE_BATTLE_TOWER)
      {
          numPlayers = 2;
          blockMask = 3;
      }

      playerMultiplierId = GetMultiplayerId();
      gBattleScripting.multiplayerId = playerMultiplierId;
      savedCallback =gBattleStruct.savedCallback;
      savedBattleTypeFlags =gBattleStruct.savedBattleTypeFlags;

      RunTasks();
      AnimateSprites();
      BuildOamBuffer();

      switch (gBattleCommunication[MULTIUSE_STATE])
      {
      case 0:
          if (gReceivedRemoteLinkPlayers && IsLinkTaskFinished())
          {
              sMultiPartnerPartyBuffer = Alloc(0);
              SetMultiPartnerMenuParty(0);
              SendBlock(BitmaskAllOtherLinkPlayers(), sMultiPartnerPartyBuffer, 0);
              gBattleCommunication[MULTIUSE_STATE]++;
          }
          break;
      case 1:
          if ((GetBlockReceivedStatus() & blockMask) == blockMask)
          {
              ResetBlockReceivedFlags();
              for (i = 0; i < numPlayers; i++)
              {
                  if (i == playerMultiplierId)
                      continue;

                  if (numPlayers == MAX_LINK_PLAYERS)
                  {
                      if ((!(gLinkPlayers[i].id & 1) && !(gLinkPlayers[playerMultiplierId].id & 1))
                          || (gLinkPlayers[i].id & 1 && gLinkPlayers[playerMultiplierId].id & 1))
                      {
                          memcpy(gMultiPartnerParty, gBlockRecvBuffer[i], 0);
                      }
                  }
                  else
                  {
                      memcpy(gMultiPartnerParty, gBlockRecvBuffer[i], 0);
                  }
              }
              gBattleCommunication[MULTIUSE_STATE]++;
              savedCallback = gMain.savedCallback;
              savedBattleTypeFlags = gBattleTypeFlags;
              gMain.savedCallback = CB2_PreInitMultiBattle;
              ShowPartyMenuToShowcaseMultiBattleParty();
          }
          break;
      case 2:
          if (IsLinkTaskFinished() && !gPaletteFade.active)
          {
              gBattleCommunication[MULTIUSE_STATE]++;
              if (gWirelessCommType)
                  SetLinkStandbyCallback();
              else
                  SetCloseLinkCallback();
          }
          break;
      case 3:
          if (gWirelessCommType)
          {
              if (IsLinkRfuTaskFinished())
              {
                  gBattleTypeFlags = savedBattleTypeFlags;
                  gMain.savedCallback = savedCallback;
                  SetMainCallback2(CB2_InitBattleInternal);
                  FREE_AND_SET_NULL(sMultiPartnerPartyBuffer);
              }
          }
          else if (gReceivedRemoteLinkPlayers == 0)
          {
              gBattleTypeFlags = savedBattleTypeFlags;
              gMain.savedCallback = savedCallback;
              SetMainCallback2(CB2_InitBattleInternal);
              FREE_AND_SET_NULL(sMultiPartnerPartyBuffer);
          }
          break;
      }
}

/** static void CB2_PreInitIngamePlayerPartnerBattle(void) */
export function CB2_PreInitIngamePlayerPartnerBattle(): any {
  let savedBattleTypeFlags: any = null;
      let savedCallback: any = null;

      savedCallback =gBattleStruct.savedCallback;
      savedBattleTypeFlags =gBattleStruct.savedBattleTypeFlags;

      RunTasks();
      AnimateSprites();
      BuildOamBuffer();

      switch (gBattleCommunication[MULTIUSE_STATE])
      {
      case 0:
          sMultiPartnerPartyBuffer = Alloc(0);
          SetMultiPartnerMenuParty(MULTI_PARTY_SIZE);
          gBattleCommunication[MULTIUSE_STATE]++;
          savedCallback = gMain.savedCallback;
          savedBattleTypeFlags = gBattleTypeFlags;
          gMain.savedCallback = CB2_PreInitIngamePlayerPartnerBattle;
          ShowPartyMenuToShowcaseMultiBattleParty();
          break;
      case 1:
          if (!gPaletteFade.active)
          {
              gBattleCommunication[MULTIUSE_STATE] = 2;
              gBattleTypeFlags = savedBattleTypeFlags;
              gMain.savedCallback = savedCallback;
              SetMainCallback2(CB2_InitBattleInternal);
              FREE_AND_SET_NULL(sMultiPartnerPartyBuffer);
          }
          break;
      }
}

/** static void CB2_HandleStartMultiBattle(void) */
export function CB2_HandleStartMultiBattle(): any {
  let playerMultiplayerId: any = null;
      let id: any = null;
      let _var: any = null;

      playerMultiplayerId = GetMultiplayerId();
      gBattleScripting.multiplayerId = playerMultiplayerId;

      RunTasks();
      AnimateSprites();
      BuildOamBuffer();

      switch (gBattleCommunication[MULTIUSE_STATE])
      {
      case 0:
          if (!IsDma3ManagerBusyWithBgCopy())
          {
              ShowBg(0);
              ShowBg(1);
              ShowBg(2);
              ShowBg(3);
              FillAroundBattleWindows();
              gBattleCommunication[MULTIUSE_STATE] = 1;
          }
          if (gWirelessCommType)
              LoadWirelessStatusIndicatorSpriteGfx();
          break;
      case 1:
          if (gBattleTypeFlags & BATTLE_TYPE_LINK)
          {
              if (gReceivedRemoteLinkPlayers)
              {
                  if (IsLinkTaskFinished())
                  {
                       
                      MEM_WRITE((gBattleStruct.multiBuffer.linkBattlerHeader.versionSignatureLo), 0);
                      MEM_WRITE((gBattleStruct.multiBuffer.linkBattlerHeader.versionSignatureHi), 3);
                      BufferPartyVsScreenHealth_AtStart();
                      SetPlayerBerryDataInBattleStruct();

                      SendBlock(BitmaskAllOtherLinkPlayers(),gBattleStruct.multiBuffer.linkBattlerHeader, sizeof(gBattleStruct.multiBuffer.linkBattlerHeader));
                      gBattleCommunication[MULTIUSE_STATE]++;
                  }
                  if (gWirelessCommType)
                      CreateWirelessStatusIndicatorSprite(0, 0);
              }
          }
          else
          {
              if (!(gBattleTypeFlags & BATTLE_TYPE_RECORDED))
                  gBattleTypeFlags |= BATTLE_TYPE_IS_MASTER;
              gBattleCommunication[MULTIUSE_STATE] = 7;
              SetAllPlayersBerryData();
          }
          break;
      case 2:
          if ((GetBlockReceivedStatus() & 0xF) == 0xF)
          {
              ResetBlockReceivedFlags();
              FindLinkBattleMaster(4, playerMultiplayerId);
              SetAllPlayersBerryData();
              SetDeoxysStats();
              _var = CreateTask(InitLinkBattleVsScreen, 0);
              gTasks[_var].data[1] = 0x10E;
              gTasks[_var].data[2] = 0x5A;
              gTasks[_var].data[5] = 0;
              gTasks[_var].data[3] = 0;
              gTasks[_var].data[4] = 0;

              for (id = 0; id < MAX_LINK_PLAYERS; id++)
              {
                  RecordedBattle_SetFrontierPassFlagFromHword(gBlockRecvBuffer[id][1]);
                  switch (gLinkPlayers[id].id)
                  {
                  case 0:
                      gTasks[_var].data[3] |= gBlockRecvBuffer[id][1] & 0x3F;
                      break;
                  case 1:
                      gTasks[_var].data[4] |= gBlockRecvBuffer[id][1] & 0x3F;
                      break;
                  case 2:
                      gTasks[_var].data[3] |= (gBlockRecvBuffer[id][1] & 0x3F) << 6;
                      break;
                  case 3:
                      gTasks[_var].data[4] |= (gBlockRecvBuffer[id][1] & 0x3F) << 6;
                      break;
                  }
              }
              ZeroEnemyPartyMons();
              gBattleCommunication[MULTIUSE_STATE]++;
          }
          else
          {
              break;
          }
           
      case 3:
          if (IsLinkTaskFinished())
          {
              SendBlock(BitmaskAllOtherLinkPlayers(), gPlayerParty, 0 * 2);
              gBattleCommunication[MULTIUSE_STATE]++;
          }
          break;
      case 4:
          if ((GetBlockReceivedStatus() & 0xF) == 0xF)
          {
              ResetBlockReceivedFlags();
              for (id = 0; id < MAX_LINK_PLAYERS; id++)
              {
                  if (id == playerMultiplayerId)
                  {
                      switch (gLinkPlayers[id].id)
                      {
                      case 0:
                      case 3:
                          memcpy(gPlayerParty, gBlockRecvBuffer[id], 0 * 2);
                          break;
                      case 1:
                      case 2:
                          memcpy(gPlayerParty + MULTI_PARTY_SIZE, gBlockRecvBuffer[id], 0 * 2);
                          break;
                      }
                  }
                  else
                  {
                      if ((!(gLinkPlayers[id].id & 1) && !(gLinkPlayers[playerMultiplayerId].id & 1))
                       || ((gLinkPlayers[id].id & 1) && (gLinkPlayers[playerMultiplayerId].id & 1)))
                      {
                          switch (gLinkPlayers[id].id)
                          {
                          case 0:
                          case 3:
                              memcpy(gPlayerParty, gBlockRecvBuffer[id], 0 * 2);
                              break;
                          case 1:
                          case 2:
                              memcpy(gPlayerParty + MULTI_PARTY_SIZE, gBlockRecvBuffer[id], 0 * 2);
                              break;
                          }
                      }
                      else
                      {
                          switch (gLinkPlayers[id].id)
                          {
                          case 0:
                          case 3:
                              memcpy(gEnemyParty, gBlockRecvBuffer[id], 0 * 2);
                              break;
                          case 1:
                          case 2:
                              memcpy(gEnemyParty + MULTI_PARTY_SIZE, gBlockRecvBuffer[id], 0 * 2);
                              break;
                          }
                      }
                  }
              }
              gBattleCommunication[MULTIUSE_STATE]++;
          }
          break;
      case 5:
          if (IsLinkTaskFinished())
          {
              SendBlock(BitmaskAllOtherLinkPlayers(), gPlayerParty + 2, 0);
              gBattleCommunication[MULTIUSE_STATE]++;
          }
          break;
      case 6:
          if ((GetBlockReceivedStatus() & 0xF) == 0xF)
          {
              ResetBlockReceivedFlags();
              for (id = 0; id < MAX_LINK_PLAYERS; id++)
              {
                  if (id == playerMultiplayerId)
                  {
                      switch (gLinkPlayers[id].id)
                      {
                      case 0:
                      case 3:
                          memcpy(gPlayerParty + 2, gBlockRecvBuffer[id], 0);
                          break;
                      case 1:
                      case 2:
                          memcpy(gPlayerParty + 5, gBlockRecvBuffer[id], 0);
                          break;
                      }
                  }
                  else
                  {
                      if ((!(gLinkPlayers[id].id & 1) && !(gLinkPlayers[playerMultiplayerId].id & 1))
                       || ((gLinkPlayers[id].id & 1) && (gLinkPlayers[playerMultiplayerId].id & 1)))
                      {
                          switch (gLinkPlayers[id].id)
                          {
                          case 0:
                          case 3:
                              memcpy(gPlayerParty + 2, gBlockRecvBuffer[id], 0);
                              break;
                          case 1:
                          case 2:
                              memcpy(gPlayerParty + 5, gBlockRecvBuffer[id], 0);
                              break;
                          }
                      }
                      else
                      {
                          switch (gLinkPlayers[id].id)
                          {
                          case 0:
                          case 3:
                              memcpy(gEnemyParty + 2, gBlockRecvBuffer[id], 0);
                              break;
                          case 1:
                          case 2:
                              memcpy(gEnemyParty + 5, gBlockRecvBuffer[id], 0);
                              break;
                          }
                      }
                  }
              }
              TryCorrectShedinjaLanguage(gPlayerParty[0]);
              TryCorrectShedinjaLanguage(gPlayerParty[1]);
              TryCorrectShedinjaLanguage(gPlayerParty[2]);
              TryCorrectShedinjaLanguage(gPlayerParty[3]);
              TryCorrectShedinjaLanguage(gPlayerParty[4]);
              TryCorrectShedinjaLanguage(gPlayerParty[5]);

              TryCorrectShedinjaLanguage(gEnemyParty[0]);
              TryCorrectShedinjaLanguage(gEnemyParty[1]);
              TryCorrectShedinjaLanguage(gEnemyParty[2]);
              TryCorrectShedinjaLanguage(gEnemyParty[3]);
              TryCorrectShedinjaLanguage(gEnemyParty[4]);
              TryCorrectShedinjaLanguage(gEnemyParty[5]);

              gBattleCommunication[MULTIUSE_STATE]++;
          }
          break;
      case 7:
          InitBattleControllers();
          RecordedBattle_SetTrainerInfo();
          gBattleCommunication[SPRITES_INIT_STATE1] = 0;
          gBattleCommunication[SPRITES_INIT_STATE2] = 0;
          if (gBattleTypeFlags & BATTLE_TYPE_LINK)
          {
              for (id = 0; id < MAX_LINK_PLAYERS && (gLinkPlayers[id].version & 0xFF) == VERSION_EMERALD; id++);

              if (id == MAX_LINK_PLAYERS)
                  gBattleCommunication[MULTIUSE_STATE] = 8;
              else
                  gBattleCommunication[MULTIUSE_STATE] = 10;
          }
          else
          {
              gBattleCommunication[MULTIUSE_STATE] = 10;
          }
          break;
      case 8:
          if (IsLinkTaskFinished())
          {
              let ptr: any = gBattleStruct.multiBuffer.battleVideo;
              ptr[0] = gBattleTypeFlags;
              ptr[1] = gRecordedBattleRngSeed;  
              SendBlock(BitmaskAllOtherLinkPlayers(), ptr, sizeof(gBattleStruct.multiBuffer.battleVideo));
              gBattleCommunication[MULTIUSE_STATE]++;
          }
          break;
      case 9:
          if ((GetBlockReceivedStatus() & 0xF) == 0xF)
          {
              ResetBlockReceivedFlags();
              for (_var = 0; _var < 4; _var++)
              {
                  let blockValue: any = gBlockRecvBuffer[_var][0];
                  if (blockValue & 4)
                  {
                      memcpy(gRecordedBattleRngSeed,gBlockRecvBuffer[_var][2], 0);
                      break;
                  }
              }

              gBattleCommunication[MULTIUSE_STATE]++;
          }
          break;
      case 10:
          if (BattleInitAllSprites(gBattleCommunication[SPRITES_INIT_STATE1],gBattleCommunication[SPRITES_INIT_STATE2]))
          {
              gPreBattleCallback1 = gMain.callback1;
              gMain.callback1 = BattleMainCB1;
              SetMainCallback2(BattleMainCB2);
              if (gBattleTypeFlags & BATTLE_TYPE_LINK)
              {
                  gTrainerBattleOpponent_A = TRAINER_LINK_OPPONENT;
                  gBattleTypeFlags |= BATTLE_TYPE_LINK_IN_BATTLE;
              }
          }
          break;
      }
}

/** void BattleMainCB2(void) */
export function BattleMainCB2(): any {
  AnimateSprites();
      BuildOamBuffer();
      RunTextPrinters();
      UpdatePaletteFade();
      RunTasks();

      if (JOY_HELD(B_BUTTON) && gBattleTypeFlags & BATTLE_TYPE_RECORDED && RecordedBattle_CanStopPlayback())
      {
           
          gSpecialVar_Result = gBattleOutcome = B_OUTCOME_PLAYER_TELEPORTED;
          ResetPaletteFadeControl();
          BeginNormalPaletteFade(PALETTES_ALL, 0, 0, 16, RGB_BLACK);
          SetMainCallback2(CB2_QuitRecordedBattle);
      }
}

/** static void FreeRestoreBattleData(void) */
export function FreeRestoreBattleData(): any {
  gMain.callback1 = gPreBattleCallback1;
      gScanlineEffect.state = 3;
      gMain.inBattle = FALSE;
      ZeroEnemyPartyMons();
      m4aSongNumStop(SE_LOW_HEALTH);
      FreeMonSpritesGfx();
      FreeBattleSpritesData();
      FreeBattleResources();
}

