/** static void SpriteCB_UnusedBattleInit(struct Sprite *sprite) */
export function SpriteCB_UnusedBattleInit(sprite: any): any {
  sprite.sState = 0;
      sprite.callback = SpriteCB_UnusedBattleInit_Main;
}

/** static void SpriteCB_UnusedBattleInit_Main(struct Sprite *sprite) */
export function SpriteCB_UnusedBattleInit_Main(sprite: any): any {
  let arr: any = gDecompressionBuffer;

      switch (sprite.sState)
      {
      case 0:
          sprite.sState++;
          sprite.data[1] = 0;
          sprite.data[2] = _0x281;
          sprite.data[3] = 0;
          sprite.sDelay = 1;
           
      case 1:
          sprite.sDelay--;
          if (sprite.sDelay == 0)
          {
              let i: any = null;
              let r2: any = null;
              let r0: any = null;

              sprite.sDelay = 2;
              r2 = sprite.data[1] + sprite.data[3] * 32;
              r0 = sprite.data[2] - sprite.data[3] * 32;
              for (i = 0; i < 29; i += 2)
              {
                  arr[r2 + i] = 0x3D;
                  arr[r0 + i] = 0x3D;
              }
              sprite.data[3]++;
              if (sprite.data[3] == 21)
              {
                  sprite.sState++;
                  sprite.data[1] = 32;
              }
          }
          break;
      case 2:
          sprite.data[1]--;
          if (sprite.data[1] == 20)
              SetMainCallback2(CB2_InitBattle);
          break;
      }
}

/** static u8 CreateNPCTrainerParty(struct Pokemon *party, u16 trainerNum, bool8 firstTrainer) */
export function CreateNPCTrainerParty(party: any, trainerNum: any, firstTrainer: any): any {
  let nameHash: any = 0;
      let personalityValue: any = null;
      let fixedIV: any = null;
      let i, j;
      let monsCount: any = null;

      if (trainerNum == TRAINER_SECRET_BASE)
          return 0;

      if (gBattleTypeFlags & BATTLE_TYPE_TRAINER && !(gBattleTypeFlags & (BATTLE_TYPE_FRONTIER
                                                                          | BATTLE_TYPE_EREADER_TRAINER
                                                                          | BATTLE_TYPE_TRAINER_HILL)))
      {
          if (firstTrainer == TRUE)
              ZeroEnemyPartyMons();

          if (gBattleTypeFlags & BATTLE_TYPE_TWO_OPPONENTS)
          {
              if (gTrainers[trainerNum].partySize > PARTY_SIZE / 2)
                  monsCount = PARTY_SIZE / 2;
              else
                  monsCount = gTrainers[trainerNum].partySize;
          }
          else
          {
              monsCount = gTrainers[trainerNum].partySize;
          }

          for (i = 0; i < monsCount; i++)
          {

              if (gTrainers[trainerNum].doubleBattle == TRUE)
                  personalityValue = _0x80;
              else if (gTrainers[trainerNum].encounterMusic_gender & F_TRAINER_FEMALE)
                  personalityValue = _0x78;  
              else
                  personalityValue = _0x88;  

              for (j = 0; gTrainers[trainerNum].trainerName[j] != EOS; j++)
                  nameHash += gTrainers[trainerNum].trainerName[j];

              switch (gTrainers[trainerNum].partyFlags)
              {
              case 0:
              {
                  let partyData: any = gTrainers[trainerNum].party.NoItemDefaultMoves;

                  for (j = 0; gSpeciesNames[partyData[i].species][j] != EOS; j++)
                      nameHash += gSpeciesNames[partyData[i].species][j];

                  personalityValue += nameHash << 8;
                  fixedIV = partyData[i].iv * MAX_PER_STAT_IVS / 255;
                  CreateMon(party[i], partyData[i].species, partyData[i].lvl, fixedIV, TRUE, personalityValue, OT_ID_RANDOM_NO_SHINY, 0);
                  break;
              }
              case F_TRAINER_PARTY_CUSTOM_MOVESET:
              {
                  let partyData: any = gTrainers[trainerNum].party.NoItemCustomMoves;

                  for (j = 0; gSpeciesNames[partyData[i].species][j] != EOS; j++)
                      nameHash += gSpeciesNames[partyData[i].species][j];

                  personalityValue += nameHash << 8;
                  fixedIV = partyData[i].iv * MAX_PER_STAT_IVS / 255;
                  CreateMon(party[i], partyData[i].species, partyData[i].lvl, fixedIV, TRUE, personalityValue, OT_ID_RANDOM_NO_SHINY, 0);

                  for (j = 0; j < MAX_MON_MOVES; j++)
                  {
                      SetMonData(party[i], MON_DATA_MOVE1 + j,partyData[i].moves[j]);
                      SetMonData(party[i], MON_DATA_PP1 + j,gBattleMoves[partyData[i].moves[j]].pp);
                  }
                  break;
              }
              case F_TRAINER_PARTY_HELD_ITEM:
              {
                  let partyData: any = gTrainers[trainerNum].party.ItemDefaultMoves;

                  for (j = 0; gSpeciesNames[partyData[i].species][j] != EOS; j++)
                      nameHash += gSpeciesNames[partyData[i].species][j];

                  personalityValue += nameHash << 8;
                  fixedIV = partyData[i].iv * MAX_PER_STAT_IVS / 255;
                  CreateMon(party[i], partyData[i].species, partyData[i].lvl, fixedIV, TRUE, personalityValue, OT_ID_RANDOM_NO_SHINY, 0);

                  SetMonData(party[i], MON_DATA_HELD_ITEM,partyData[i].heldItem);
                  break;
              }
              case F_TRAINER_PARTY_CUSTOM_MOVESET | F_TRAINER_PARTY_HELD_ITEM:
              {
                  let partyData: any = gTrainers[trainerNum].party.ItemCustomMoves;

                  for (j = 0; gSpeciesNames[partyData[i].species][j] != EOS; j++)
                      nameHash += gSpeciesNames[partyData[i].species][j];

                  personalityValue += nameHash << 8;
                  fixedIV = partyData[i].iv * MAX_PER_STAT_IVS / 255;
                  CreateMon(party[i], partyData[i].species, partyData[i].lvl, fixedIV, TRUE, personalityValue, OT_ID_RANDOM_NO_SHINY, 0);

                  SetMonData(party[i], MON_DATA_HELD_ITEM,partyData[i].heldItem);

                  for (j = 0; j < MAX_MON_MOVES; j++)
                  {
                      SetMonData(party[i], MON_DATA_MOVE1 + j,partyData[i].moves[j]);
                      SetMonData(party[i], MON_DATA_PP1 + j,gBattleMoves[partyData[i].moves[j]].pp);
                  }
                  break;
              }
              }
          }

          gBattleTypeFlags |= gTrainers[trainerNum].doubleBattle;
      }

      return gTrainers[trainerNum].partySize;
}

/** void VBlankCB_Battle(void) */
export function VBlankCB_Battle(): any {
  if (!(gBattleTypeFlags & (BATTLE_TYPE_LINK | BATTLE_TYPE_FRONTIER | BATTLE_TYPE_RECORDED)))
          Random();

      SetGpuReg(REG_OFFSET_BG0HOFS, gBattle_BG0_X);
      SetGpuReg(REG_OFFSET_BG0VOFS, gBattle_BG0_Y);
      SetGpuReg(REG_OFFSET_BG1HOFS, gBattle_BG1_X);
      SetGpuReg(REG_OFFSET_BG1VOFS, gBattle_BG1_Y);
      SetGpuReg(REG_OFFSET_BG2HOFS, gBattle_BG2_X);
      SetGpuReg(REG_OFFSET_BG2VOFS, gBattle_BG2_Y);
      SetGpuReg(REG_OFFSET_BG3HOFS, gBattle_BG3_X);
      SetGpuReg(REG_OFFSET_BG3VOFS, gBattle_BG3_Y);
      SetGpuReg(REG_OFFSET_WIN0H, gBattle_WIN0H);
      SetGpuReg(REG_OFFSET_WIN0V, gBattle_WIN0V);
      SetGpuReg(REG_OFFSET_WIN1H, gBattle_WIN1H);
      SetGpuReg(REG_OFFSET_WIN1V, gBattle_WIN1V);
      LoadOam();
      ProcessSpriteCopyRequests();
      TransferPlttBuffer();
      ScanlineEffect_InitHBlankDmaTransfer();
}

/** static void SpriteCB_VsLetter(struct Sprite *sprite) */
export function SpriteCB_VsLetter(sprite: any): any {
  if (sprite.data[0] != 0)
          sprite.x = sprite.data[1] + ((sprite.data[2] & 0xFF00) >> 8);
      else
          sprite.x = sprite.data[1] - ((sprite.data[2] & 0xFF00) >> 8);

      sprite.data[2] += _0x180;

      if (sprite.affineAnimEnded)
      {
          FreeSpriteTilesByTag(ANIM_SPRITES_START);
          FreeSpritePaletteByTag(ANIM_SPRITES_START);
          FreeSpriteOamMatrix(sprite);
          DestroySprite(sprite);
      }
}

