/** static void AskRecordBattle(void) */
export function AskRecordBattle(): any {
  switch (gBattleCommunication[MULTIUSE_STATE])
      {
      case STATE_INIT:
          ShowBg(0);
          ShowBg(1);
          ShowBg(2);
          gBattleCommunication[MULTIUSE_STATE]++;
          break;
      case STATE_LINK:
          if (gMain.anyLinkBattlerHasFrontierPass && gReceivedRemoteLinkPlayers == 0)
              CreateTask(Task_ReconnectWithLinkPlayers, 5);
          gBattleCommunication[MULTIUSE_STATE]++;
          break;
      case STATE_WAIT_LINK:
          if (!FuncIsActiveTask(Task_ReconnectWithLinkPlayers))
              gBattleCommunication[MULTIUSE_STATE]++;
          break;
      case STATE_ASK_RECORD:
          if (!gPaletteFade.active)
          {
               
              BattlePutTextOnWindow(gText_RecordBattleToPass, B_WIN_MSG);
              gBattleCommunication[MULTIUSE_STATE]++;
          }
          break;
      case STATE_PRINT_YES_NO:
          if (!IsTextPrinterActive(B_WIN_MSG))
          {
              HandleBattleWindow(YESNOBOX_X_Y, 0);
              BattlePutTextOnWindow(gText_BattleYesNoChoice, B_WIN_YESNO);
              gBattleCommunication[CURSOR_POSITION] = 1;
              BattleCreateYesNoCursorAt(1);
              gBattleCommunication[MULTIUSE_STATE]++;
          }
          break;
      case STATE_HANDLE_YES_NO:
          if (JOY_NEW(DPAD_UP))
          {
              if (gBattleCommunication[CURSOR_POSITION] != 0)
              {
                   
                  PlaySE(SE_SELECT);
                  BattleDestroyYesNoCursorAt(gBattleCommunication[CURSOR_POSITION]);
                  gBattleCommunication[CURSOR_POSITION] = 0;
                  BattleCreateYesNoCursorAt(0);
              }
          }
          else if (JOY_NEW(DPAD_DOWN))
          {
              if (gBattleCommunication[CURSOR_POSITION] == 0)
              {
                   
                  PlaySE(SE_SELECT);
                  BattleDestroyYesNoCursorAt(gBattleCommunication[CURSOR_POSITION]);
                  gBattleCommunication[CURSOR_POSITION] = 1;
                  BattleCreateYesNoCursorAt(1);
              }
          }
          else if (JOY_NEW(A_BUTTON))
          {
              PlaySE(SE_SELECT);
              if (gBattleCommunication[CURSOR_POSITION] == 0)
              {
                   
                  HandleBattleWindow(YESNOBOX_X_Y, WINDOW_CLEAR);
                  gBattleCommunication[1] = MoveRecordedBattleToSaveData();
                  gBattleCommunication[MULTIUSE_STATE] = STATE_RECORD_YES;
              }
              else
              {
                   
                  gBattleCommunication[MULTIUSE_STATE]++;
              }
          }
          else if (JOY_NEW(B_BUTTON))
          {
              PlaySE(SE_SELECT);
              gBattleCommunication[MULTIUSE_STATE]++;
          }
          break;
      case STATE_RECORD_NO:
          if (IsLinkTaskFinished() == TRUE)
          {
              HandleBattleWindow(YESNOBOX_X_Y, WINDOW_CLEAR);
              if (gMain.anyLinkBattlerHasFrontierPass)
              {
                   
                  SetLinkStandbyCallback();
                  BattlePutTextOnWindow(gText_LinkStandby3, B_WIN_MSG);
              }
              gBattleCommunication[MULTIUSE_STATE]++;  
          }
          break;
      case STATE_WAIT_END:
          if (--gBattleCommunication[1] == 0)
          {
              if (gMain.anyLinkBattlerHasFrontierPass && !gWirelessCommType)
                  SetCloseLinkCallback();
              gBattleCommunication[MULTIUSE_STATE]++;
          }
          break;
      case STATE_END:
          if (!gMain.anyLinkBattlerHasFrontierPass || gWirelessCommType || gReceivedRemoteLinkPlayers != 1)
          {
              gMain.anyLinkBattlerHasFrontierPass = FALSE;
              if (!gPaletteFade.active)
              {
                  SetMainCallback2(gMain.savedCallback);
                  FreeBattleResources();
                  FreeBattleSpritesData();
                  FreeMonSpritesGfx();
              }
          }
          break;
      case STATE_RECORD_YES:
          if (gBattleCommunication[1] == 1)
          {
              PlaySE(SE_SAVE);
              BattleStringExpandPlaceholdersToDisplayedString(gText_BattleRecordedOnPass);
              BattlePutTextOnWindow(gDisplayedStringBattle, B_WIN_MSG);
              gBattleCommunication[1] = 128;  
              gBattleCommunication[MULTIUSE_STATE]++;
          }
          else
          {
              BattleStringExpandPlaceholdersToDisplayedString(BattleFrontier_BattleTowerBattleRoom_Text_RecordCouldntBeSaved);
              BattlePutTextOnWindow(gDisplayedStringBattle, B_WIN_MSG);
              gBattleCommunication[1] = 128;  
              gBattleCommunication[MULTIUSE_STATE]++;
          }
          break;
      case STATE_RECORD_WAIT:
          if (IsLinkTaskFinished() == TRUE && !IsTextPrinterActive(B_WIN_MSG) && --gBattleCommunication[1] == 0)
          {
              if (gMain.anyLinkBattlerHasFrontierPass)
              {
                  SetLinkStandbyCallback();
                  BattlePutTextOnWindow(gText_LinkStandby3, B_WIN_MSG);
              }
              gBattleCommunication[MULTIUSE_STATE]++;
          }
          break;
      case STATE_END_RECORD_YES:
      case STATE_END_RECORD_NO:
          if (!IsTextPrinterActive(B_WIN_MSG))
          {
              if (gMain.anyLinkBattlerHasFrontierPass)
              {
                  if (IsLinkTaskFinished() == TRUE)
                  {
                      BeginNormalPaletteFade(PALETTES_ALL, 0, 0, 16, RGB_BLACK);
                      gBattleCommunication[1] = 32;  
                      gBattleCommunication[MULTIUSE_STATE] = STATE_WAIT_END;
                  }

              }
              else
              {
                  BeginNormalPaletteFade(PALETTES_ALL, 0, 0, 16, RGB_BLACK);
                  gBattleCommunication[1] = 32;  
                  gBattleCommunication[MULTIUSE_STATE] = STATE_WAIT_END;
              }
          }
          break;
      }
}

/** static void TryCorrectShedinjaLanguage(struct Pokemon *mon) */
export function TryCorrectShedinjaLanguage(mon: any): any {
  const nickname: any[] = [];
      let language: any = LANGUAGE_JAPANESE;

      if (GetMonData(mon, MON_DATA_SPECIES) == SPECIES_SHEDINJA
       && GetMonData(mon, MON_DATA_LANGUAGE) != language)
      {
          GetMonData(mon, MON_DATA_NICKNAME, nickname);
          if (StringCompareWithoutExtCtrlCodes(nickname, sText_ShedinjaJpnName) == 0)
              SetMonData(mon, MON_DATA_LANGUAGE,language);
      }
}

