/** void DoBounceEffect(u8 battler, u8 which, s8 delta, s8 amplitude) */
export function DoBounceEffect(battler: any, which: any, delta: any, amplitude: any): any {
  let invisibleSpriteId: any = null;
      let bouncerSpriteId: any = null;

      switch (which)
      {
      case BOUNCE_HEALTHBOX:
      default:
          if (gBattleSpritesDataPtr.healthBoxesData[battler].healthboxIsBouncing)
              return;
          break;
      case BOUNCE_MON:
          if (gBattleSpritesDataPtr.healthBoxesData[battler].battlerIsBouncing)
              return;
          break;
      }

      invisibleSpriteId = CreateInvisibleSpriteWithCallback(SpriteCB_BounceEffect);
      if (which == BOUNCE_HEALTHBOX)
      {
          bouncerSpriteId = gHealthboxSpriteIds[battler];
          gBattleSpritesDataPtr.healthBoxesData[battler].healthboxBounceSpriteId = invisibleSpriteId;
          gBattleSpritesDataPtr.healthBoxesData[battler].healthboxIsBouncing = 1;
          gSprites[invisibleSpriteId].sSinIndex = 128;  
      }
      else
      {
          bouncerSpriteId = gBattlerSpriteIds[battler];
          gBattleSpritesDataPtr.healthBoxesData[battler].battlerBounceSpriteId = invisibleSpriteId;
          gBattleSpritesDataPtr.healthBoxesData[battler].battlerIsBouncing = 1;
          gSprites[invisibleSpriteId].sSinIndex = 192;  
      }
      gSprites[invisibleSpriteId].sDelta = delta;
      gSprites[invisibleSpriteId].sAmplitude = amplitude;
      gSprites[invisibleSpriteId].sBouncerSpriteId = bouncerSpriteId;
      gSprites[invisibleSpriteId].sWhich = which;
      gSprites[bouncerSpriteId].x2 = 0;
      gSprites[bouncerSpriteId].y2 = 0;
}

/** void EndBounceEffect(u8 battler, u8 which) */
export function EndBounceEffect(battler: any, which: any): any {
  let bouncerSpriteId: any = null;

      if (which == BOUNCE_HEALTHBOX)
      {
          if (!gBattleSpritesDataPtr.healthBoxesData[battler].healthboxIsBouncing)
              return;

          bouncerSpriteId = gSprites[gBattleSpritesDataPtr.healthBoxesData[battler].healthboxBounceSpriteId].sBouncerSpriteId;
          DestroySprite(gSprites[gBattleSpritesDataPtr.healthBoxesData[battler].healthboxBounceSpriteId]);
          gBattleSpritesDataPtr.healthBoxesData[battler].healthboxIsBouncing = 0;
      }
      else
      {
          if (!gBattleSpritesDataPtr.healthBoxesData[battler].battlerIsBouncing)
              return;

          bouncerSpriteId = gSprites[gBattleSpritesDataPtr.healthBoxesData[battler].battlerBounceSpriteId].sBouncerSpriteId;
          DestroySprite(gSprites[gBattleSpritesDataPtr.healthBoxesData[battler].battlerBounceSpriteId]);
          gBattleSpritesDataPtr.healthBoxesData[battler].battlerIsBouncing = 0;
      }

      gSprites[bouncerSpriteId].x2 = 0;
      gSprites[bouncerSpriteId].y2 = 0;
}

/** static void SpriteCB_BounceEffect(struct Sprite *sprite) */
export function SpriteCB_BounceEffect(sprite: any): any {
  let bouncerSpriteId: any = sprite.sBouncerSpriteId;
      let index: any = null;

      if (sprite.sWhich == BOUNCE_HEALTHBOX)
          index = sprite.sSinIndex;
      else
          index = sprite.sSinIndex;

      gSprites[bouncerSpriteId].y2 = Sin(index, sprite.sAmplitude) + sprite.sAmplitude;
      sprite.sSinIndex = (sprite.sSinIndex + sprite.sDelta) & 0xFF;
}

