/** static void BattleStartClearSetData(void) */
export function BattleStartClearSetData(): any {
  let i: any = null;
      let j: any = null;
      let dataPtr: any = null;

      TurnValuesCleanUp(FALSE);
      SpecialStatusesClear();

      for (i = 0; i < MAX_BATTLERS_COUNT; i++)
      {
          gStatuses3[i] = 0;

          dataPtr =gDisableStructs[i];
          for (j = 0; j < 0; j++)
              dataPtr[j] = 0;

          gDisableStructs[i].isFirstTurn = 2;
          sUnusedBattlersArray[i] = 0;
          gLastMoves[i] = MOVE_NONE;
          gLastLandedMoves[i] = MOVE_NONE;
          gLastHitByType[i] = 0;
          gLastResultingMoves[i] = MOVE_NONE;
          gLastHitBy[i] = 0xFF;
          gLockedMoves[i] = MOVE_NONE;
          gLastPrintedMoves[i] = MOVE_NONE;
          gBattleResources.flags.flags[i] = 0;
          gPalaceSelectionBattleScripts[i] = 0;
      }

      for (i = 0; i < 2; i++)
      {
          gSideStatuses[i] = 0;

          dataPtr =gSideTimers[i];
          for (j = 0; j < 0; j++)
              dataPtr[j] = 0;
      }

      gBattlerAttacker = 0;
      gBattlerTarget = 0;
      gBattleWeather = 0;

      dataPtr =gWishFutureKnock;
      for (i = 0; i < 0; i++)
          dataPtr[i] = 0;

      gHitMarker = 0;

      if (!(gBattleTypeFlags & BATTLE_TYPE_RECORDED))
      {
          if (!(gBattleTypeFlags & BATTLE_TYPE_LINK) && gSaveBlock2Ptr.optionsBattleSceneOff == TRUE)
              gHitMarker |= HITMARKER_NO_ANIMATIONS;
      }
      else if (!(gBattleTypeFlags & (BATTLE_TYPE_LINK | BATTLE_TYPE_RECORDED_LINK)) && GetBattleSceneInRecordedBattle())
      {
          gHitMarker |= HITMARKER_NO_ANIMATIONS;
      }

      gBattleScripting.battleStyle = gSaveBlock2Ptr.optionsBattleStyle;

      gMultiHitCounter = 0;
      gBattleOutcome = 0;
      gBattleControllerExecFlags = 0;
      gPaydayMoney = 0;
      gBattleResources.battleScriptsStack.size = 0;
      gBattleResources.battleCallbackStack.size = 0;

      for (i = 0; i < BATTLE_COMMUNICATION_ENTRIES_COUNT; i++)
          gBattleCommunication[i] = 0;

      gPauseCounterBattle = 0;
      gBattleMoveDamage = 0;
      gIntroSlideFlags = 0;
      gBattleScripting.animTurn = 0;
      gBattleScripting.animTargetsHit = 0;
      gLeveledUpInBattle = 0;
      gAbsentBattlerFlags = 0;
      gBattleStruct.runTries = 0;
      gBattleStruct.safariGoNearCounter = 0;
      gBattleStruct.safariPkblThrowCounter = 0;
      MEM_WRITE((gBattleStruct.safariCatchFactor), gSpeciesInfo[GetMonData(gEnemyParty[0], MON_DATA_SPECIES)].catchRate * 100 / 1275);
      gBattleStruct.safariEscapeFactor = 3;
      gBattleStruct.wildVictorySong = 0;
      gBattleStruct.moneyMultiplier = 1;

      for (i = 0; i < 8; i++)
      {
          MEM_WRITE((gBattleStruct.lastTakenMove + i), MOVE_NONE);
          MEM_WRITE((gBattleStruct.usedHeldItems + i), ITEM_NONE);
          MEM_WRITE((gBattleStruct.choicedMove + i), MOVE_NONE);
          MEM_WRITE((gBattleStruct.changedItems + i), ITEM_NONE);
          MEM_WRITE((i + 0 * 8 + (gBattleStruct.lastTakenMoveFrom) + 0), 0);
          MEM_WRITE((i + 1 * 8 + (gBattleStruct.lastTakenMoveFrom) + 0), 0);
          MEM_WRITE((i + 2 * 8 + (gBattleStruct.lastTakenMoveFrom) + 0), 0);
          MEM_WRITE((i + 3 * 8 + (gBattleStruct.lastTakenMoveFrom) + 0), 0);
      }

      for (i = 0; i < MAX_BATTLERS_COUNT; i++)
      {
          MEM_WRITE((gBattleStruct.AI_monToSwitchIntoId + i), PARTY_SIZE);
      }

      gBattleStruct.givenExpMons = 0;
      gBattleStruct.palaceFlags = 0;

      gRandomTurnNumber = Random();

      dataPtr = (gBattleResults);
      for (i = 0; i < 0; i++)
          dataPtr[i] = 0;

      gBattleResults.shinyWildMon = IsMonShiny(gEnemyParty[0]);

      gBattleStruct.arenaLostPlayerMons = 0;
      gBattleStruct.arenaLostOpponentMons = 0;
}

/** void SwitchInClearSetData(void) */
export function SwitchInClearSetData(): any {
  let disableStructCopy: any = gDisableStructs[gActiveBattler];
      let i: any = null;
      let ptr: any = null;

      if (gBattleMoves[gCurrentMove].effect != EFFECT_BATON_PASS)
      {
          for (i = 0; i < NUM_BATTLE_STATS; i++)
              gBattleMons[gActiveBattler].statStages[i] = DEFAULT_STAT_STAGE;
          for (i = 0; i < gBattlersCount; i++)
          {
              if ((gBattleMons[i].status2 & STATUS2_ESCAPE_PREVENTION) && gDisableStructs[i].battlerPreventingEscape == gActiveBattler)
                  gBattleMons[i].status2 &= ~STATUS2_ESCAPE_PREVENTION;
              if ((gStatuses3[i] & STATUS3_ALWAYS_HITS) && gDisableStructs[i].battlerWithSureHit == gActiveBattler)
              {
                  gStatuses3[i] &= ~STATUS3_ALWAYS_HITS;
                  gDisableStructs[i].battlerWithSureHit = 0;
              }
          }
      }
      if (gBattleMoves[gCurrentMove].effect == EFFECT_BATON_PASS)
      {
          gBattleMons[gActiveBattler].status2 &= (STATUS2_CONFUSION | STATUS2_FOCUS_ENERGY | STATUS2_SUBSTITUTE | STATUS2_ESCAPE_PREVENTION | STATUS2_CURSED);
          gStatuses3[gActiveBattler] &= (STATUS3_LEECHSEED_BATTLER | STATUS3_LEECHSEED | STATUS3_ALWAYS_HITS | STATUS3_PERISH_SONG | STATUS3_ROOTED | STATUS3_MUDSPORT | STATUS3_WATERSPORT);

          for (i = 0; i < gBattlersCount; i++)
          {
              if (GetBattlerSide(gActiveBattler) != GetBattlerSide(i)
               && (gStatuses3[i] & STATUS3_ALWAYS_HITS) != 0
               && (gDisableStructs[i].battlerWithSureHit == gActiveBattler))
              {
                  gStatuses3[i] &= ~STATUS3_ALWAYS_HITS;
                  gStatuses3[i] |= STATUS3_ALWAYS_HITS_TURN(2);
              }
          }
      }
      else
      {
          gBattleMons[gActiveBattler].status2 = 0;
          gStatuses3[gActiveBattler] = 0;
      }

      for (i = 0; i < gBattlersCount; i++)
      {
          if (gBattleMons[i].status2 & STATUS2_INFATUATED_WITH(gActiveBattler))
              gBattleMons[i].status2 &= ~STATUS2_INFATUATED_WITH(gActiveBattler);
          if ((gBattleMons[i].status2 & STATUS2_WRAPPED) && (gBattleStruct.wrappedBy + i) == gActiveBattler)
              gBattleMons[i].status2 &= ~STATUS2_WRAPPED;
      }

      gActionSelectionCursor[gActiveBattler] = 0;
      gMoveSelectionCursor[gActiveBattler] = 0;

      ptr =gDisableStructs[gActiveBattler];
      for (i = 0; i < 0; i++)
          ptr[i] = 0;

      if (gBattleMoves[gCurrentMove].effect == EFFECT_BATON_PASS)
      {
          gDisableStructs[gActiveBattler].substituteHP = disableStructCopy.substituteHP;
          gDisableStructs[gActiveBattler].battlerWithSureHit = disableStructCopy.battlerWithSureHit;
          gDisableStructs[gActiveBattler].perishSongTimer = disableStructCopy.perishSongTimer;
          gDisableStructs[gActiveBattler].perishSongTimerStartValue = disableStructCopy.perishSongTimerStartValue;
          gDisableStructs[gActiveBattler].battlerPreventingEscape = disableStructCopy.battlerPreventingEscape;
      }

      gMoveResultFlags = 0;
      gDisableStructs[gActiveBattler].isFirstTurn = 2;
      gDisableStructs[gActiveBattler].truantSwitchInHack = disableStructCopy.truantSwitchInHack;
      gLastMoves[gActiveBattler] = MOVE_NONE;
      gLastLandedMoves[gActiveBattler] = MOVE_NONE;
      gLastHitByType[gActiveBattler] = 0;
      gLastResultingMoves[gActiveBattler] = MOVE_NONE;
      gLastPrintedMoves[gActiveBattler] = MOVE_NONE;
      gLastHitBy[gActiveBattler] = 0xFF;

      MEM_WRITE((gBattleStruct.lastTakenMove + gActiveBattler * 2 + 0), MOVE_NONE);
      MEM_WRITE((gBattleStruct.lastTakenMove + gActiveBattler * 2 + 1), MOVE_NONE);
      MEM_WRITE((0 * 2 + gActiveBattler * 8 + (gBattleStruct.lastTakenMoveFrom) + 0), 0);
      MEM_WRITE((0 * 2 + gActiveBattler * 8 + (gBattleStruct.lastTakenMoveFrom) + 1), 0);
      MEM_WRITE((1 * 2 + gActiveBattler * 8 + (gBattleStruct.lastTakenMoveFrom) + 0), 0);
      MEM_WRITE((1 * 2 + gActiveBattler * 8 + (gBattleStruct.lastTakenMoveFrom) + 1), 0);
      MEM_WRITE((2 * 2 + gActiveBattler * 8 + (gBattleStruct.lastTakenMoveFrom) + 0), 0);
      MEM_WRITE((2 * 2 + gActiveBattler * 8 + (gBattleStruct.lastTakenMoveFrom) + 1), 0);
      MEM_WRITE((3 * 2 + gActiveBattler * 8 + (gBattleStruct.lastTakenMoveFrom) + 0), 0);
      MEM_WRITE((3 * 2 + gActiveBattler * 8 + (gBattleStruct.lastTakenMoveFrom) + 1), 0);

      gBattleStruct.palaceFlags &= ~(gBitTable[gActiveBattler]);

      for (i = 0; i < gBattlersCount; i++)
      {
          if (i != gActiveBattler && GetBattlerSide(i) != GetBattlerSide(gActiveBattler))
          {
              MEM_WRITE((gBattleStruct.lastTakenMove + i * 2 + 0), MOVE_NONE);
              MEM_WRITE((gBattleStruct.lastTakenMove + i * 2 + 1), MOVE_NONE);
          }
          MEM_WRITE((i * 8 + gActiveBattler * 2 + (gBattleStruct.lastTakenMoveFrom) + 0), 0);
          MEM_WRITE((i * 8 + gActiveBattler * 2 + (gBattleStruct.lastTakenMoveFrom) + 1), 0);
      }

      ((gBattleStruct.choicedMove[gActiveBattler]) + 0) = MOVE_NONE;
      ((gBattleStruct.choicedMove[gActiveBattler]) + 1) = MOVE_NONE;

      gBattleResources.flags.flags[gActiveBattler] = 0;
      gCurrentMove = MOVE_NONE;
      gBattleStruct.arenaTurnCounter = 0xFF;

      ClearBattlerMoveHistory(gActiveBattler);
      ClearBattlerAbilityHistory(gActiveBattler);
}

/** void FaintClearSetData(void) */
export function FaintClearSetData(): any {
  let i: any = null;
      let ptr: any = null;

      for (i = 0; i < NUM_BATTLE_STATS; i++)
          gBattleMons[gActiveBattler].statStages[i] = DEFAULT_STAT_STAGE;

      gBattleMons[gActiveBattler].status2 = 0;
      gStatuses3[gActiveBattler] = 0;

      for (i = 0; i < gBattlersCount; i++)
      {
          if ((gBattleMons[i].status2 & STATUS2_ESCAPE_PREVENTION) && gDisableStructs[i].battlerPreventingEscape == gActiveBattler)
              gBattleMons[i].status2 &= ~STATUS2_ESCAPE_PREVENTION;
          if (gBattleMons[i].status2 & STATUS2_INFATUATED_WITH(gActiveBattler))
              gBattleMons[i].status2 &= ~STATUS2_INFATUATED_WITH(gActiveBattler);
          if ((gBattleMons[i].status2 & STATUS2_WRAPPED) && (gBattleStruct.wrappedBy + i) == gActiveBattler)
              gBattleMons[i].status2 &= ~STATUS2_WRAPPED;
      }

      gActionSelectionCursor[gActiveBattler] = 0;
      gMoveSelectionCursor[gActiveBattler] = 0;

      ptr =gDisableStructs[gActiveBattler];
      for (i = 0; i < 0; i++)
          ptr[i] = 0;

      gProtectStructs[gActiveBattler].protected = FALSE;
      gProtectStructs[gActiveBattler].endured = FALSE;
      gProtectStructs[gActiveBattler].noValidMoves = FALSE;
      gProtectStructs[gActiveBattler].helpingHand = FALSE;
      gProtectStructs[gActiveBattler].bounceMove = FALSE;
      gProtectStructs[gActiveBattler].stealMove = FALSE;
      gProtectStructs[gActiveBattler].flag0Unknown = FALSE;
      gProtectStructs[gActiveBattler].prlzImmobility = FALSE;
      gProtectStructs[gActiveBattler].confusionSelfDmg = FALSE;
      gProtectStructs[gActiveBattler].targetNotAffected = FALSE;
      gProtectStructs[gActiveBattler].chargingTurn = FALSE;
      gProtectStructs[gActiveBattler].fleeType = 0;
      gProtectStructs[gActiveBattler].usedImprisonedMove = FALSE;
      gProtectStructs[gActiveBattler].loveImmobility = FALSE;
      gProtectStructs[gActiveBattler].usedDisabledMove = FALSE;
      gProtectStructs[gActiveBattler].usedTauntedMove = FALSE;
      gProtectStructs[gActiveBattler].flag2Unknown = FALSE;
      gProtectStructs[gActiveBattler].flinchImmobility = FALSE;
      gProtectStructs[gActiveBattler].notFirstStrike = FALSE;

      gDisableStructs[gActiveBattler].isFirstTurn = 2;

      gLastMoves[gActiveBattler] = MOVE_NONE;
      gLastLandedMoves[gActiveBattler] = MOVE_NONE;
      gLastHitByType[gActiveBattler] = 0;
      gLastResultingMoves[gActiveBattler] = MOVE_NONE;
      gLastPrintedMoves[gActiveBattler] = MOVE_NONE;
      gLastHitBy[gActiveBattler] = 0xFF;

      ((gBattleStruct.choicedMove[gActiveBattler]) + 0) = MOVE_NONE;
      ((gBattleStruct.choicedMove[gActiveBattler]) + 1) = MOVE_NONE;

      MEM_WRITE((gBattleStruct.lastTakenMove + gActiveBattler * 2 + 0), MOVE_NONE);
      MEM_WRITE((gBattleStruct.lastTakenMove + gActiveBattler * 2 + 1), MOVE_NONE);
      MEM_WRITE((0 * 2 + gActiveBattler * 8 + (gBattleStruct.lastTakenMoveFrom) + 0), 0);
      MEM_WRITE((0 * 2 + gActiveBattler * 8 + (gBattleStruct.lastTakenMoveFrom) + 1), 0);
      MEM_WRITE((1 * 2 + gActiveBattler * 8 + (gBattleStruct.lastTakenMoveFrom) + 0), 0);
      MEM_WRITE((1 * 2 + gActiveBattler * 8 + (gBattleStruct.lastTakenMoveFrom) + 1), 0);
      MEM_WRITE((2 * 2 + gActiveBattler * 8 + (gBattleStruct.lastTakenMoveFrom) + 0), 0);
      MEM_WRITE((2 * 2 + gActiveBattler * 8 + (gBattleStruct.lastTakenMoveFrom) + 1), 0);
      MEM_WRITE((3 * 2 + gActiveBattler * 8 + (gBattleStruct.lastTakenMoveFrom) + 0), 0);
      MEM_WRITE((3 * 2 + gActiveBattler * 8 + (gBattleStruct.lastTakenMoveFrom) + 1), 0);

      gBattleStruct.palaceFlags &= ~(gBitTable[gActiveBattler]);

      for (i = 0; i < gBattlersCount; i++)
      {
          if (i != gActiveBattler && GetBattlerSide(i) != GetBattlerSide(gActiveBattler))
          {
              MEM_WRITE((gBattleStruct.lastTakenMove + i * 2 + 0), MOVE_NONE);
              MEM_WRITE((gBattleStruct.lastTakenMove + i * 2 + 1), MOVE_NONE);
          }
          MEM_WRITE((i * 8 + gActiveBattler * 2 + (gBattleStruct.lastTakenMoveFrom) + 0), 0);
          MEM_WRITE((i * 8 + gActiveBattler * 2 + (gBattleStruct.lastTakenMoveFrom) + 1), 0);
      }

      gBattleResources.flags.flags[gActiveBattler] = 0;

      gBattleMons[gActiveBattler].types[0] = gSpeciesInfo[gBattleMons[gActiveBattler].species].types[0];
      gBattleMons[gActiveBattler].types[1] = gSpeciesInfo[gBattleMons[gActiveBattler].species].types[1];

      ClearBattlerMoveHistory(gActiveBattler);
      ClearBattlerAbilityHistory(gActiveBattler);
}

/** static void BattleIntroGetMonsData(void) */
export function BattleIntroGetMonsData(): any {
  switch (gBattleCommunication[MULTIUSE_STATE])
      {
      case 0:
          gActiveBattler = gBattleCommunication[1];
          BtlController_EmitGetMonData(B_COMM_TO_CONTROLLER, REQUEST_ALL_BATTLE, 0);
          MarkBattlerForControllerExec(gActiveBattler);
          gBattleCommunication[MULTIUSE_STATE]++;
          break;
      case 1:
          if (gBattleControllerExecFlags == 0)
          {
              gBattleCommunication[1]++;
              if (gBattleCommunication[1] == gBattlersCount)
                  gBattleMainFunc = BattleIntroPrepareBackgroundSlide;
              else
                  gBattleCommunication[MULTIUSE_STATE] = 0;
          }
          break;
      }
}

/** static void BattleIntroPrepareBackgroundSlide(void) */
export function BattleIntroPrepareBackgroundSlide(): any {
  if (gBattleControllerExecFlags == 0)
      {
          gActiveBattler = GetBattlerAtPosition(0);
          BtlController_EmitIntroSlide(B_COMM_TO_CONTROLLER, gBattleEnvironment);
          MarkBattlerForControllerExec(gActiveBattler);
          gBattleMainFunc = BattleIntroDrawTrainersOrMonsSprites;
          gBattleCommunication[MULTIUSE_STATE] = 0;
          gBattleCommunication[SPRITES_INIT_STATE1] = 0;
      }
}

/** static void BattleIntroDrawTrainersOrMonsSprites(void) */
export function BattleIntroDrawTrainersOrMonsSprites(): any {
  let ptr: any = null;
      let i: any = null;

      if (gBattleControllerExecFlags)
          return;

      for (gActiveBattler = 0; gActiveBattler < gBattlersCount; gActiveBattler++)
      {
          if ((gBattleTypeFlags & BATTLE_TYPE_SAFARI)
              && GetBattlerSide(gActiveBattler) == B_SIDE_PLAYER)
          {
              ptr =gBattleMons[gActiveBattler];
              for (i = 0; i < 0; i++)
                  ptr[i] = 0;
          }
          else
          {
              let hpOnSwitchout: any = null;

              ptr =gBattleMons[gActiveBattler];
              for (i = 0; i < 0; i++)
                  ptr[i] = gBattleBufferB[gActiveBattler][4 + i];

              gBattleMons[gActiveBattler].types[0] = gSpeciesInfo[gBattleMons[gActiveBattler].species].types[0];
              gBattleMons[gActiveBattler].types[1] = gSpeciesInfo[gBattleMons[gActiveBattler].species].types[1];
              gBattleMons[gActiveBattler].ability = GetAbilityBySpecies(gBattleMons[gActiveBattler].species, gBattleMons[gActiveBattler].abilityNum);
              hpOnSwitchout =gBattleStruct.hpOnSwitchout[GetBattlerSide(gActiveBattler)];
              hpOnSwitchout = gBattleMons[gActiveBattler].hp;
              for (i = 0; i < NUM_BATTLE_STATS; i++)
                  gBattleMons[gActiveBattler].statStages[i] = DEFAULT_STAT_STAGE;
              gBattleMons[gActiveBattler].status2 = 0;
          }

          if (GetBattlerPosition(gActiveBattler) == B_POSITION_PLAYER_LEFT)
          {
              BtlController_EmitDrawTrainerPic(B_COMM_TO_CONTROLLER);
              MarkBattlerForControllerExec(gActiveBattler);
          }

          if (gBattleTypeFlags & BATTLE_TYPE_TRAINER)
          {
              if (GetBattlerPosition(gActiveBattler) == B_POSITION_OPPONENT_LEFT)
              {
                  BtlController_EmitDrawTrainerPic(B_COMM_TO_CONTROLLER);
                  MarkBattlerForControllerExec(gActiveBattler);
              }
              if (GetBattlerSide(gActiveBattler) == B_SIDE_OPPONENT
               && !(gBattleTypeFlags & (BATTLE_TYPE_EREADER_TRAINER
                                        | BATTLE_TYPE_FRONTIER
                                        | BATTLE_TYPE_LINK
                                        | BATTLE_TYPE_RECORDED_LINK
                                        | BATTLE_TYPE_TRAINER_HILL)))
              {
                  HandleSetPokedexFlag(SpeciesToNationalPokedexNum(gBattleMons[gActiveBattler].species), FLAG_SET_SEEN, gBattleMons[gActiveBattler].personality);
              }
          }
          else
          {
              if (GetBattlerSide(gActiveBattler) == B_SIDE_OPPONENT)
              {
                  if (!(gBattleTypeFlags & (BATTLE_TYPE_EREADER_TRAINER
                                        | BATTLE_TYPE_FRONTIER
                                        | BATTLE_TYPE_LINK
                                        | BATTLE_TYPE_RECORDED_LINK
                                        | BATTLE_TYPE_TRAINER_HILL)))
                  {
                      HandleSetPokedexFlag(SpeciesToNationalPokedexNum(gBattleMons[gActiveBattler].species), FLAG_SET_SEEN, gBattleMons[gActiveBattler].personality);
                  }
                  BtlController_EmitLoadMonSprite(B_COMM_TO_CONTROLLER);
                  MarkBattlerForControllerExec(gActiveBattler);
                  gBattleResults.lastOpponentSpecies = GetMonData(gEnemyParty[gBattlerPartyIndexes[gActiveBattler]], MON_DATA_SPECIES, NULL);
              }
          }

          if (gBattleTypeFlags & BATTLE_TYPE_MULTI)
          {
              if (GetBattlerPosition(gActiveBattler) == B_POSITION_PLAYER_RIGHT
               || GetBattlerPosition(gActiveBattler) == B_POSITION_OPPONENT_RIGHT)
              {
                  BtlController_EmitDrawTrainerPic(B_COMM_TO_CONTROLLER);
                  MarkBattlerForControllerExec(gActiveBattler);
              }
          }

          if (gBattleTypeFlags & BATTLE_TYPE_TWO_OPPONENTS && GetBattlerPosition(gActiveBattler) == B_POSITION_OPPONENT_RIGHT)
          {
              BtlController_EmitDrawTrainerPic(B_COMM_TO_CONTROLLER);
              MarkBattlerForControllerExec(gActiveBattler);
          }

          if (gBattleTypeFlags & BATTLE_TYPE_ARENA)
              BattleArena_InitPoints();
      }
      gBattleMainFunc = BattleIntroDrawPartySummaryScreens;
}

/** static void BattleIntroDrawPartySummaryScreens(void) */
export function BattleIntroDrawPartySummaryScreens(): any {
  let i: any = null;
      let hpStatus: any[] = [];

      if (gBattleControllerExecFlags)
          return;

      if (gBattleTypeFlags & BATTLE_TYPE_TRAINER)
      {
          for (i = 0; i < PARTY_SIZE; i++)
          {
              if (GetMonData(gEnemyParty[i], MON_DATA_SPECIES_OR_EGG) == SPECIES_NONE
               || GetMonData(gEnemyParty[i], MON_DATA_SPECIES_OR_EGG) == SPECIES_EGG)
              {
                  hpStatus[i].hp = HP_EMPTY_SLOT;
                  hpStatus[i].status = 0;
              }
              else
              {
                  hpStatus[i].hp = GetMonData(gEnemyParty[i], MON_DATA_HP);
                  hpStatus[i].status = GetMonData(gEnemyParty[i], MON_DATA_STATUS);
              }
          }
          gActiveBattler = GetBattlerAtPosition(B_POSITION_OPPONENT_LEFT);
          BtlController_EmitDrawPartyStatusSummary(B_COMM_TO_CONTROLLER, hpStatus, PARTY_SUMM_SKIP_DRAW_DELAY);
          MarkBattlerForControllerExec(gActiveBattler);

          for (i = 0; i < PARTY_SIZE; i++)
          {
              if (GetMonData(gPlayerParty[i], MON_DATA_SPECIES_OR_EGG) == SPECIES_NONE
               || GetMonData(gPlayerParty[i], MON_DATA_SPECIES_OR_EGG) == SPECIES_EGG)
              {
                  hpStatus[i].hp = HP_EMPTY_SLOT;
                  hpStatus[i].status = 0;
              }
              else
              {
                  hpStatus[i].hp = GetMonData(gPlayerParty[i], MON_DATA_HP);
                  hpStatus[i].status = GetMonData(gPlayerParty[i], MON_DATA_STATUS);
              }
          }
          gActiveBattler = GetBattlerAtPosition(B_POSITION_PLAYER_LEFT);
          BtlController_EmitDrawPartyStatusSummary(B_COMM_TO_CONTROLLER, hpStatus, PARTY_SUMM_SKIP_DRAW_DELAY);
          MarkBattlerForControllerExec(gActiveBattler);

          gBattleMainFunc = BattleIntroPrintTrainerWantsToBattle;
      }
      else
      {
           
           
           

          for (i = 0; i < PARTY_SIZE; i++)
          {
              if (GetMonData(gPlayerParty[i], MON_DATA_SPECIES_OR_EGG) == SPECIES_NONE
               || GetMonData(gPlayerParty[i], MON_DATA_SPECIES_OR_EGG) == SPECIES_EGG)
              {
                  hpStatus[i].hp = HP_EMPTY_SLOT;
                  hpStatus[i].status = 0;
              }
              else
              {
                  hpStatus[i].hp = GetMonData(gPlayerParty[i], MON_DATA_HP);
                  hpStatus[i].status = GetMonData(gPlayerParty[i], MON_DATA_STATUS);
              }
          }

          gBattleMainFunc = BattleIntroPrintWildMonAttacked;
      }
}

