/** static void TryDoEventsBeforeFirstTurn(void) */
export function TryDoEventsBeforeFirstTurn(): any {
  let i: any = null;
      let j: any = null;
      let effect: any = 0;

      if (gBattleControllerExecFlags)
          return;

      if (gBattleStruct.switchInAbilitiesCounter == 0)
      {
          for (i = 0; i < gBattlersCount; i++)
              gBattlerByTurnOrder[i] = i;
          for (i = 0; i < gBattlersCount - 1; i++)
          {
              for (j = i + 1; j < gBattlersCount; j++)
              {
                  if (GetWhoStrikesFirst(gBattlerByTurnOrder[i], gBattlerByTurnOrder[j], TRUE) != 0)
                      SwapTurnOrder(i, j);
              }
          }
      }
      if (!gBattleStruct.overworldWeatherDone
          && AbilityBattleEffects(0, 0, 0, ABILITYEFFECT_SWITCH_IN_WEATHER, 0) != 0)
      {
          gBattleStruct.overworldWeatherDone = TRUE;
          return;
      }
       
      while (gBattleStruct.switchInAbilitiesCounter < gBattlersCount)
      {
          if (AbilityBattleEffects(ABILITYEFFECT_ON_SWITCHIN, gBattlerByTurnOrder[gBattleStruct.switchInAbilitiesCounter], 0, 0, 0) != 0)
              effect++;

          gBattleStruct.switchInAbilitiesCounter++;

          if (effect != 0)
              return;
      }
      if (AbilityBattleEffects(ABILITYEFFECT_INTIMIDATE1, 0, 0, 0, 0) != 0)
          return;
      if (AbilityBattleEffects(ABILITYEFFECT_TRACE, 0, 0, 0, 0) != 0)
          return;
       
      while (gBattleStruct.switchInItemsCounter < gBattlersCount)
      {
          if (ItemBattleEffects(ITEMEFFECT_ON_SWITCH_IN, gBattlerByTurnOrder[gBattleStruct.switchInItemsCounter], FALSE))
              effect++;

          gBattleStruct.switchInItemsCounter++;

          if (effect != 0)
              return;
      }
      for (i = 0; i < MAX_BATTLERS_COUNT; i++)
      {
          MEM_WRITE((gBattleStruct.monToSwitchIntoId + i), PARTY_SIZE);
          gChosenActionByBattler[i] = B_ACTION_NONE;
          gChosenMoveByBattler[i] = MOVE_NONE;
      }
      TurnValuesCleanUp(FALSE);
      SpecialStatusesClear();
      MEM_WRITE((gBattleStruct.absentBattlerFlags), gAbsentBattlerFlags);
      BattlePutTextOnWindow(gText_EmptyString3, B_WIN_MSG);
      gBattleMainFunc = HandleTurnActionSelectionState;
      ResetSentPokesToOpponentValue();

      for (i = 0; i < BATTLE_COMMUNICATION_ENTRIES_COUNT; i++)
          gBattleCommunication[i] = 0;

      for (i = 0; i < gBattlersCount; i++)
          gBattleMons[i].status2 &= ~STATUS2_FLINCHED;

      MEM_WRITE((gBattleStruct.turnEffectsTracker), 0);
      MEM_WRITE((gBattleStruct.turnEffectsBattlerId), 0);
      MEM_WRITE((gBattleStruct.wishPerishSongState), 0);
      MEM_WRITE((gBattleStruct.wishPerishSongBattlerId), 0);
      gBattleScripting.moveendState = 0;
      gBattleStruct.faintedActionsState = 0;
      gBattleStruct.turnCountersTracker = 0;
      gMoveResultFlags = 0;

      gRandomTurnNumber = Random();

      if (gBattleTypeFlags & BATTLE_TYPE_ARENA)
      {
          StopCryAndClearCrySongs();
          BattleScriptExecute(BattleScript_ArenaTurnBeginning);
      }
}

/** static void HandleEndTurn_ContinueBattle(void) */
export function HandleEndTurn_ContinueBattle(): any {
  let i: any = null;

      if (gBattleControllerExecFlags == 0)
      {
          gBattleMainFunc = BattleTurnPassed;
          for (i = 0; i < BATTLE_COMMUNICATION_ENTRIES_COUNT; i++)
              gBattleCommunication[i] = 0;
          for (i = 0; i < gBattlersCount; i++)
          {
              gBattleMons[i].status2 &= ~STATUS2_FLINCHED;
              if ((gBattleMons[i].status1 & STATUS1_SLEEP) && (gBattleMons[i].status2 & STATUS2_MULTIPLETURNS))
                  CancelMultiTurnMoves(i);
          }
          gBattleStruct.turnEffectsTracker = 0;
          gBattleStruct.turnEffectsBattlerId = 0;
          gBattleStruct.wishPerishSongState = 0;
          gBattleStruct.wishPerishSongBattlerId = 0;
          gBattleStruct.turnCountersTracker = 0;
          gMoveResultFlags = 0;
      }
}

/** void BattleTurnPassed(void) */
export function BattleTurnPassed(): any {
  let i: any = null;

      TurnValuesCleanUp(TRUE);
      if (gBattleOutcome == 0)
      {
          if (DoFieldEndTurnEffects())
              return;
          if (DoBattlerEndTurnEffects())
              return;
      }
      if (HandleFaintedMonActions())
          return;
      gBattleStruct.faintedActionsState = 0;
      if (HandleWishPerishSongOnTurnEnd())
          return;

      TurnValuesCleanUp(FALSE);
      gHitMarker &= ~HITMARKER_NO_ATTACKSTRING;
      gHitMarker &= ~HITMARKER_UNABLE_TO_USE_MOVE;
      gHitMarker &= ~HITMARKER_PLAYER_FAINTED;
      gHitMarker &= ~HITMARKER_PASSIVE_HP_UPDATE;
      gBattleScripting.animTurn = 0;
      gBattleScripting.animTargetsHit = 0;
      gBattleScripting.moveendState = 0;
      gBattleMoveDamage = 0;
      gMoveResultFlags = 0;

      for (i = 0; i < 5; i++)
          gBattleCommunication[i] = 0;

      if (gBattleOutcome != 0)
      {
          gCurrentActionFuncId = B_ACTION_FINISHED;
          gBattleMainFunc = RunTurnActionsFunctions;
          return;
      }

      if (gBattleResults.battleTurnCounter < 0xFF)
      {
          gBattleResults.battleTurnCounter++;
          gBattleStruct.arenaTurnCounter++;
      }

      for (i = 0; i < gBattlersCount; i++)
      {
          gChosenActionByBattler[i] = B_ACTION_NONE;
          gChosenMoveByBattler[i] = MOVE_NONE;
      }

      for (i = 0; i < MAX_BATTLERS_COUNT; i++)
          MEM_WRITE((gBattleStruct.monToSwitchIntoId + i), PARTY_SIZE);

      MEM_WRITE((gBattleStruct.absentBattlerFlags), gAbsentBattlerFlags);
      BattlePutTextOnWindow(gText_EmptyString3, B_WIN_MSG);
      gBattleMainFunc = HandleTurnActionSelectionState;
      gRandomTurnNumber = Random();

      if (gBattleTypeFlags & BATTLE_TYPE_PALACE)
          BattleScriptExecute(BattleScript_PalacePrintFlavorText);
      else if (gBattleTypeFlags & BATTLE_TYPE_ARENA && gBattleStruct.arenaTurnCounter == 0)
          BattleScriptExecute(BattleScript_ArenaTurnBeginning);
}

/** u8 IsRunningFromBattleImpossible(void) */
export function IsRunningFromBattleImpossible(): any {
  let holdEffect: any = null;
      let side: any = null;
      let i: any = null;

      if (gBattleMons[gActiveBattler].item == ITEM_ENIGMA_BERRY)
          holdEffect = gEnigmaBerries[gActiveBattler].holdEffect;
      else
          holdEffect = GetItemHoldEffect(gBattleMons[gActiveBattler].item);

      gPotentialItemEffectBattler = gActiveBattler;

      if (holdEffect == HOLD_EFFECT_CAN_ALWAYS_RUN)
          return BATTLE_RUN_SUCCESS;
      if (gBattleTypeFlags & BATTLE_TYPE_LINK)
          return BATTLE_RUN_SUCCESS;
      if (gBattleMons[gActiveBattler].ability == ABILITY_RUN_AWAY)
          return BATTLE_RUN_SUCCESS;

      side = GetBattlerSide(gActiveBattler);

      for (i = 0; i < gBattlersCount; i++)
      {
          if (side != GetBattlerSide(i)
           && gBattleMons[i].ability == ABILITY_SHADOW_TAG)
          {
              gBattleScripting.battler = i;
              gLastUsedAbility = gBattleMons[i].ability;
              gBattleCommunication[MULTISTRING_CHOOSER] = B_MSG_PREVENTS_ESCAPE;
              return BATTLE_RUN_FAILURE;
          }
          if (side != GetBattlerSide(i)
           && gBattleMons[gActiveBattler].ability != ABILITY_LEVITATE
           && !IS_BATTLER_OF_TYPE(gActiveBattler, TYPE_FLYING)
           && gBattleMons[i].ability == ABILITY_ARENA_TRAP)
          {
              gBattleScripting.battler = i;
              gLastUsedAbility = gBattleMons[i].ability;
              gBattleCommunication[MULTISTRING_CHOOSER] = B_MSG_PREVENTS_ESCAPE;
              return BATTLE_RUN_FAILURE;
          }
      }
      i = AbilityBattleEffects(ABILITYEFFECT_CHECK_FIELD_EXCEPT_BATTLER, gActiveBattler, ABILITY_MAGNET_PULL, 0, 0);
      if (i != 0 && IS_BATTLER_OF_TYPE(gActiveBattler, TYPE_STEEL))
      {
          gBattleScripting.battler = i - 1;
          gLastUsedAbility = gBattleMons[i - 1].ability;
          gBattleCommunication[MULTISTRING_CHOOSER] = B_MSG_PREVENTS_ESCAPE;
          return BATTLE_RUN_FAILURE;
      }
      if ((gBattleMons[gActiveBattler].status2 & (STATUS2_ESCAPE_PREVENTION | STATUS2_WRAPPED))
          || (gStatuses3[gActiveBattler] & STATUS3_ROOTED))
      {
          gBattleCommunication[MULTISTRING_CHOOSER] = B_MSG_CANT_ESCAPE;
          return BATTLE_RUN_FORBIDDEN;
      }
      if (gBattleTypeFlags & BATTLE_TYPE_FIRST_BATTLE)
      {
          gBattleCommunication[MULTISTRING_CHOOSER] = B_MSG_DONT_LEAVE_BIRCH;
          return BATTLE_RUN_FORBIDDEN;
      }
      return BATTLE_RUN_SUCCESS;
}

/** void SwitchPartyOrder(u8 battler) */
export function SwitchPartyOrder(battler: any): any {
  let i: any = null;
      let partyId1: any = null;
      let partyId2: any = null;

      for (i = 0; i < ARRAY_COUNT(gBattlePartyCurrentOrder); i++)
          gBattlePartyCurrentOrder[i] = (battler * 3 + i + (gBattleStruct.battlerPartyOrders));

      partyId1 = GetPartyIdFromBattlePartyId(gBattlerPartyIndexes[battler]);
      partyId2 = GetPartyIdFromBattlePartyId((gBattleStruct.monToSwitchIntoId + battler));
      SwitchPartyMonSlots(partyId1, partyId2);

      if (gBattleTypeFlags & BATTLE_TYPE_DOUBLE)
      {
          for (i = 0; i < ARRAY_COUNT(gBattlePartyCurrentOrder); i++)
          {
              MEM_WRITE((battler * 3 + i + (gBattleStruct.battlerPartyOrders)), gBattlePartyCurrentOrder[i]);
              MEM_WRITE((BATTLE_PARTNER(battler) * 3 + i + (gBattleStruct.battlerPartyOrders)), gBattlePartyCurrentOrder[i]);
          }
      }
      else
      {
          for (i = 0; i < ARRAY_COUNT(gBattlePartyCurrentOrder); i++)
          {
              MEM_WRITE((battler * 3 + i + (gBattleStruct.battlerPartyOrders)), gBattlePartyCurrentOrder[i]);
          }
      }
}

/** static void HandleTurnActionSelectionState(void) */
export function HandleTurnActionSelectionState(): any {
  let i: any = null;

      gBattleCommunication[ACTIONS_CONFIRMED_COUNT] = 0;
      for (gActiveBattler = 0; gActiveBattler < gBattlersCount; gActiveBattler++)
      {
          let position: any = GetBattlerPosition(gActiveBattler);
          switch (gBattleCommunication[gActiveBattler])
          {
          case STATE_TURN_START_RECORD:  
              RecordedBattle_CopyBattlerMoves();
              gBattleCommunication[gActiveBattler] = STATE_BEFORE_ACTION_CHOSEN;
              break;
          case STATE_BEFORE_ACTION_CHOSEN:  
              MEM_WRITE((gBattleStruct.monToSwitchIntoId + gActiveBattler), PARTY_SIZE);
              if (gBattleTypeFlags & BATTLE_TYPE_MULTI
                  || (position & BIT_FLANK) == B_FLANK_LEFT
                  || gBattleStruct.absentBattlerFlags & gBitTable[GetBattlerAtPosition(BATTLE_PARTNER(position))]
                  || gBattleCommunication[GetBattlerAtPosition(BATTLE_PARTNER(position))] == STATE_WAIT_ACTION_CONFIRMED)
              {
                  if (gBattleStruct.absentBattlerFlags & gBitTable[gActiveBattler])
                  {
                      gChosenActionByBattler[gActiveBattler] = B_ACTION_NOTHING_FAINTED;
                      if (!(gBattleTypeFlags & BATTLE_TYPE_MULTI))
                          gBattleCommunication[gActiveBattler] = STATE_WAIT_ACTION_CONFIRMED;
                      else
                          gBattleCommunication[gActiveBattler] = STATE_WAIT_ACTION_CONFIRMED_STANDBY;
                  }
                  else
                  {
                      if (gBattleMons[gActiveBattler].status2 & STATUS2_MULTIPLETURNS
                          || gBattleMons[gActiveBattler].status2 & STATUS2_RECHARGE)
                      {
                          gChosenActionByBattler[gActiveBattler] = B_ACTION_USE_MOVE;
                          gBattleCommunication[gActiveBattler] = STATE_WAIT_ACTION_CONFIRMED_STANDBY;
                      }
                      else
                      {
                          BtlController_EmitChooseAction(B_COMM_TO_CONTROLLER, gChosenActionByBattler[0], gBattleBufferB[0][1] | (gBattleBufferB[0][2] << 8));
                          MarkBattlerForControllerExec(gActiveBattler);
                          gBattleCommunication[gActiveBattler]++;
                      }
                  }
              }
              break;
          case STATE_WAIT_ACTION_CHOSEN:  
              if (!IS_BATTLE_CONTROLLER_ACTIVE_OR_PENDING_SYNC_ANYWHERE(gActiveBattler))
              {
                  RecordedBattle_SetBattlerAction(gActiveBattler, gBattleBufferB[gActiveBattler][1]);
                  gChosenActionByBattler[gActiveBattler] = gBattleBufferB[gActiveBattler][1];

                  switch (gBattleBufferB[gActiveBattler][1])
                  {
                  case B_ACTION_USE_MOVE:
                      if (AreAllMovesUnusable())
                      {
                          gBattleCommunication[gActiveBattler] = STATE_SELECTION_SCRIPT;
                          MEM_WRITE((gBattleStruct.selectionScriptFinished + gActiveBattler), FALSE);
                          MEM_WRITE((gBattleStruct.stateIdAfterSelScript + gActiveBattler), STATE_WAIT_ACTION_CONFIRMED_STANDBY);
                          MEM_WRITE((gBattleStruct.moveTarget + gActiveBattler), gBattleBufferB[gActiveBattler][3]);
                          return;
                      }
                      else if (gDisableStructs[gActiveBattler].encoredMove != 0)
                      {
                          gChosenMoveByBattler[gActiveBattler] = gDisableStructs[gActiveBattler].encoredMove;
                          MEM_WRITE((gBattleStruct.chosenMovePositions + gActiveBattler), gDisableStructs[gActiveBattler].encoredMovePos);
                          gBattleCommunication[gActiveBattler] = STATE_WAIT_ACTION_CONFIRMED_STANDBY;
                          return;
                      }
                      else
                      {
                          let moveInfo: any = null;

                          moveInfo.species = gBattleMons[gActiveBattler].species;
                          moveInfo.monTypes[0] = gBattleMons[gActiveBattler].types[0];
                          moveInfo.monTypes[1] = gBattleMons[gActiveBattler].types[1];

                          for (i = 0; i < MAX_MON_MOVES; i++)
                          {
                              moveInfo.moves[i] = gBattleMons[gActiveBattler].moves[i];
                              moveInfo.currentPp[i] = gBattleMons[gActiveBattler].pp[i];
                              moveInfo.maxPp[i] = CalculatePPWithBonus(
                                                              gBattleMons[gActiveBattler].moves[i],
                                                              gBattleMons[gActiveBattler].ppBonuses,
                                                              i);
                          }

                          BtlController_EmitChooseMove(B_COMM_TO_CONTROLLER, (gBattleTypeFlags & BATTLE_TYPE_DOUBLE) != 0, FALSE,moveInfo);
                          MarkBattlerForControllerExec(gActiveBattler);
                      }
                      break;
                  case B_ACTION_USE_ITEM:
                      if (gBattleTypeFlags & (BATTLE_TYPE_LINK
                                              | BATTLE_TYPE_FRONTIER_NO_PYRAMID
                                              | BATTLE_TYPE_EREADER_TRAINER
                                              | BATTLE_TYPE_RECORDED_LINK))
                      {
                          RecordedBattle_ClearBattlerAction(gActiveBattler, 1);
                          gSelectionBattleScripts[gActiveBattler] = BattleScript_ActionSelectionItemsCantBeUsed;
                          gBattleCommunication[gActiveBattler] = STATE_SELECTION_SCRIPT;
                          MEM_WRITE((gBattleStruct.selectionScriptFinished + gActiveBattler), FALSE);
                          MEM_WRITE((gBattleStruct.stateIdAfterSelScript + gActiveBattler), STATE_BEFORE_ACTION_CHOSEN);
                          return;
                      }
                      else
                      {
                          BtlController_EmitChooseItem(B_COMM_TO_CONTROLLER, gBattleStruct.battlerPartyOrders[gActiveBattler]);
                          MarkBattlerForControllerExec(gActiveBattler);
                      }
                      break;
                  case B_ACTION_SWITCH:
                      MEM_WRITE((gBattleStruct.battlerPartyIndexes + gActiveBattler), gBattlerPartyIndexes[gActiveBattler]);
                      if (gBattleMons[gActiveBattler].status2 & (STATUS2_WRAPPED | STATUS2_ESCAPE_PREVENTION)
                          || gBattleTypeFlags & BATTLE_TYPE_ARENA
                          || gStatuses3[gActiveBattler] & STATUS3_ROOTED)
                      {
                          BtlController_EmitChoosePokemon(B_COMM_TO_CONTROLLER, PARTY_ACTION_CANT_SWITCH, PARTY_SIZE, ABILITY_NONE, gBattleStruct.battlerPartyOrders[gActiveBattler]);
                      }
                      else if ((i = ABILITY_ON_OPPOSING_FIELD(gActiveBattler, ABILITY_SHADOW_TAG))
                               || ((i = ABILITY_ON_OPPOSING_FIELD(gActiveBattler, ABILITY_ARENA_TRAP))
                                   && !IS_BATTLER_OF_TYPE(gActiveBattler, TYPE_FLYING)
                                   && gBattleMons[gActiveBattler].ability != ABILITY_LEVITATE)
                               || ((i = AbilityBattleEffects(ABILITYEFFECT_CHECK_FIELD_EXCEPT_BATTLER, gActiveBattler, ABILITY_MAGNET_PULL, 0, 0))
                                   && IS_BATTLER_OF_TYPE(gActiveBattler, TYPE_STEEL)))
                      {
                          BtlController_EmitChoosePokemon(B_COMM_TO_CONTROLLER, ((i - 1) << 4) | PARTY_ACTION_ABILITY_PREVENTS, PARTY_SIZE, gLastUsedAbility, gBattleStruct.battlerPartyOrders[gActiveBattler]);
                      }
                      else
                      {
                          if (gActiveBattler == 2 && gChosenActionByBattler[0] == B_ACTION_SWITCH)
                              BtlController_EmitChoosePokemon(B_COMM_TO_CONTROLLER, PARTY_ACTION_CHOOSE_MON, (gBattleStruct.monToSwitchIntoId + 0), ABILITY_NONE, gBattleStruct.battlerPartyOrders[gActiveBattler]);
                          else if (gActiveBattler == 3 && gChosenActionByBattler[1] == B_ACTION_SWITCH)
                              BtlController_EmitChoosePokemon(B_COMM_TO_CONTROLLER, PARTY_ACTION_CHOOSE_MON, (gBattleStruct.monToSwitchIntoId + 1), ABILITY_NONE, gBattleStruct.battlerPartyOrders[gActiveBattler]);
                          else
                              BtlController_EmitChoosePokemon(B_COMM_TO_CONTROLLER, PARTY_ACTION_CHOOSE_MON, PARTY_SIZE, ABILITY_NONE, gBattleStruct.battlerPartyOrders[gActiveBattler]);
                      }
                      MarkBattlerForControllerExec(gActiveBattler);
                      break;
                  case B_ACTION_SAFARI_BALL:
                      if (IsPlayerPartyAndPokemonStorageFull())
                      {
                          gSelectionBattleScripts[gActiveBattler] = BattleScript_PrintFullBox;
                          gBattleCommunication[gActiveBattler] = STATE_SELECTION_SCRIPT;
                          MEM_WRITE((gBattleStruct.selectionScriptFinished + gActiveBattler), FALSE);
                          MEM_WRITE((gBattleStruct.stateIdAfterSelScript + gActiveBattler), STATE_BEFORE_ACTION_CHOSEN);
                          return;
                      }
                      break;
                  case B_ACTION_SAFARI_POKEBLOCK:
                      BtlController_EmitChooseItem(B_COMM_TO_CONTROLLER, gBattleStruct.battlerPartyOrders[gActiveBattler]);
                      MarkBattlerForControllerExec(gActiveBattler);
                      break;
                  case B_ACTION_CANCEL_PARTNER:
                      gBattleCommunication[gActiveBattler] = STATE_WAIT_SET_BEFORE_ACTION;
                      gBattleCommunication[GetBattlerAtPosition(BATTLE_PARTNER(GetBattlerPosition(gActiveBattler)))] = STATE_BEFORE_ACTION_CHOSEN;
                      RecordedBattle_ClearBattlerAction(gActiveBattler, 1);
                      if (gBattleMons[GetBattlerAtPosition(BATTLE_PARTNER(GetBattlerPosition(gActiveBattler)))].status2 & STATUS2_MULTIPLETURNS
                          || gBattleMons[GetBattlerAtPosition(BATTLE_PARTNER(GetBattlerPosition(gActiveBattler)))].status2 & STATUS2_RECHARGE)
                      {
                          BtlController_EmitEndBounceEffect(B_COMM_TO_CONTROLLER);
                          MarkBattlerForControllerExec(gActiveBattler);
                          return;
                      }
                      else if (gChosenActionByBattler[GetBattlerAtPosition(BATTLE_PARTNER(GetBattlerPosition(gActiveBattler)))] == B_ACTION_SWITCH)
                      {
                          RecordedBattle_ClearBattlerAction(GetBattlerAtPosition(BATTLE_PARTNER(GetBattlerPosition(gActiveBattler))), 2);
                      }
                      else if (gChosenActionByBattler[GetBattlerAtPosition(BATTLE_PARTNER(GetBattlerPosition(gActiveBattler)))] == B_ACTION_RUN)
                      {
                          RecordedBattle_ClearBattlerAction(GetBattlerAtPosition(BATTLE_PARTNER(GetBattlerPosition(gActiveBattler))), 1);
                      }
                      else if (gChosenActionByBattler[GetBattlerAtPosition(BATTLE_PARTNER(GetBattlerPosition(gActiveBattler)))] == B_ACTION_USE_MOVE
                               && (gProtectStructs[GetBattlerAtPosition(BATTLE_PARTNER(GetBattlerPosition(gActiveBattler)))].noValidMoves
                                  || gDisableStructs[GetBattlerAtPosition(BATTLE_PARTNER(GetBattlerPosition(gActiveBattler)))].encoredMove))
                      {
                          RecordedBattle_ClearBattlerAction(GetBattlerAtPosition(BATTLE_PARTNER(GetBattlerPosition(gActiveBattler))), 1);
                      }
                      else if (gBattleTypeFlags & BATTLE_TYPE_PALACE
                               && gChosenActionByBattler[GetBattlerAtPosition(BATTLE_PARTNER(GetBattlerPosition(gActiveBattler)))] == B_ACTION_USE_MOVE)
                      {
                          gRngValue = gBattlePalaceMoveSelectionRngValue;
                          RecordedBattle_ClearBattlerAction(GetBattlerAtPosition(BATTLE_PARTNER(GetBattlerPosition(gActiveBattler))), 1);
                      }
                      else
                      {
                          RecordedBattle_ClearBattlerAction(GetBattlerAtPosition(BATTLE_PARTNER(GetBattlerPosition(gActiveBattler))), 3);
                      }
                      BtlController_EmitEndBounceEffect(B_COMM_TO_CONTROLLER);
                      MarkBattlerForControllerExec(gActiveBattler);
                      return;
                  }

                  if (gBattleTypeFlags & BATTLE_TYPE_TRAINER
                      && gBattleTypeFlags & (BATTLE_TYPE_FRONTIER | BATTLE_TYPE_TRAINER_HILL)
                      && gBattleBufferB[gActiveBattler][1] == B_ACTION_RUN)
                  {
                      gSelectionBattleScripts[gActiveBattler] = BattleScript_AskIfWantsToForfeitMatch;
                      gBattleCommunication[gActiveBattler] = STATE_SELECTION_SCRIPT_MAY_RUN;
                      MEM_WRITE((gBattleStruct.selectionScriptFinished + gActiveBattler), FALSE);
                      MEM_WRITE((gBattleStruct.stateIdAfterSelScript + gActiveBattler), STATE_BEFORE_ACTION_CHOSEN);
                      return;
                  }
                  else if (gBattleTypeFlags & BATTLE_TYPE_TRAINER
                           && !(gBattleTypeFlags & (BATTLE_TYPE_LINK | BATTLE_TYPE_RECORDED_LINK))
                           && gBattleBufferB[gActiveBattler][1] == B_ACTION_RUN)
                  {
                      BattleScriptExecute(BattleScript_PrintCantRunFromTrainer);
                      gBattleCommunication[gActiveBattler] = STATE_BEFORE_ACTION_CHOSEN;
                  }
                  else if (IsRunningFromBattleImpossible() != BATTLE_RUN_SUCCESS
                           && gBattleBufferB[gActiveBattler][1] == B_ACTION_RUN)
                  {
                      gSelectionBattleScripts[gActiveBattler] = BattleScript_PrintCantEscapeFromBattle;
                      gBattleCommunication[gActiveBattler] = STATE_SELECTION_SCRIPT;
                      MEM_WRITE((gBattleStruct.selectionScriptFinished + gActiveBattler), FALSE);
                      MEM_WRITE((gBattleStruct.stateIdAfterSelScript + gActiveBattler), STATE_BEFORE_ACTION_CHOSEN);
                      return;
                  }
                  else
                  {
                      gBattleCommunication[gActiveBattler]++;
                  }
              }
              break;
          case STATE_WAIT_ACTION_CASE_CHOSEN:
              if (!IS_BATTLE_CONTROLLER_ACTIVE_OR_PENDING_SYNC_ANYWHERE(gActiveBattler))
              {
                  switch (gChosenActionByBattler[gActiveBattler])
                  {
                  case B_ACTION_USE_MOVE:
                      switch (gBattleBufferB[gActiveBattler][1])
                      {
                      case 3:
                      case 4:
                      case 5:
                      case 6:
                      case 7:
                      case 8:
                      case 9:
                          gChosenActionByBattler[gActiveBattler] = gBattleBufferB[gActiveBattler][1];
                          return;
                      case 15:
                          gChosenActionByBattler[gActiveBattler] = B_ACTION_SWITCH;
                          UpdateBattlerPartyOrdersOnSwitch();
                          return;
                      default:
                          RecordedBattle_CheckMovesetChanges(B_RECORD_MODE_PLAYBACK);
                          if ((gBattleBufferB[gActiveBattler][2] | (gBattleBufferB[gActiveBattler][3] << 8)) == 0xFFFF)
                          {
                              gBattleCommunication[gActiveBattler] = STATE_BEFORE_ACTION_CHOSEN;
                              RecordedBattle_ClearBattlerAction(gActiveBattler, 1);
                          }
                          else if (TrySetCantSelectMoveBattleScript())
                          {
                              RecordedBattle_ClearBattlerAction(gActiveBattler, 1);
                              gBattleCommunication[gActiveBattler] = STATE_SELECTION_SCRIPT;
                              MEM_WRITE((gBattleStruct.selectionScriptFinished + gActiveBattler), FALSE);
                              gBattleBufferB[gActiveBattler][1] = B_ACTION_USE_MOVE;
                              MEM_WRITE((gBattleStruct.stateIdAfterSelScript + gActiveBattler), STATE_WAIT_ACTION_CHOSEN);
                              return;
                          }
                          else
                          {
                              if (!(gBattleTypeFlags & BATTLE_TYPE_PALACE))
                              {
                                  RecordedBattle_SetBattlerAction(gActiveBattler, gBattleBufferB[gActiveBattler][2]);
                                  RecordedBattle_SetBattlerAction(gActiveBattler, gBattleBufferB[gActiveBattler][3]);
                              }
                              MEM_WRITE((gBattleStruct.chosenMovePositions + gActiveBattler), gBattleBufferB[gActiveBattler][2]);
                              gChosenMoveByBattler[gActiveBattler] = gBattleMons[gActiveBattler].moves[(gBattleStruct.chosenMovePositions + gActiveBattler)];
                              MEM_WRITE((gBattleStruct.moveTarget + gActiveBattler), gBattleBufferB[gActiveBattler][3]);
                              gBattleCommunication[gActiveBattler]++;
                          }
                          break;
                      }
                      break;
                  case B_ACTION_USE_ITEM:
                      if ((gBattleBufferB[gActiveBattler][1] | (gBattleBufferB[gActiveBattler][2] << 8)) == 0)
                      {
                          gBattleCommunication[gActiveBattler] = STATE_BEFORE_ACTION_CHOSEN;
                      }
                      else
                      {
                          gLastUsedItem = (gBattleBufferB[gActiveBattler][1] | (gBattleBufferB[gActiveBattler][2] << 8));
                          gBattleCommunication[gActiveBattler]++;
                      }
                      break;
                  case B_ACTION_SWITCH:
                      if (gBattleBufferB[gActiveBattler][1] == PARTY_SIZE)
                      {
                          gBattleCommunication[gActiveBattler] = STATE_BEFORE_ACTION_CHOSEN;
                          RecordedBattle_ClearBattlerAction(gActiveBattler, 1);
                      }
                      else
                      {
                          UpdateBattlerPartyOrdersOnSwitch();
                          gBattleCommunication[gActiveBattler]++;
                      }
                      break;
                  case B_ACTION_RUN:
                      gHitMarker |= HITMARKER_RUN;
                      gBattleCommunication[gActiveBattler]++;
                      break;
                  case B_ACTION_SAFARI_WATCH_CAREFULLY:
                      gBattleCommunication[gActiveBattler]++;
                      break;
                  case B_ACTION_SAFARI_BALL:
                      gBattleCommunication[gActiveBattler]++;
                      break;
                  case B_ACTION_SAFARI_POKEBLOCK:
                      if ((gBattleBufferB[gActiveBattler][1] | (gBattleBufferB[gActiveBattler][2] << 8)) != 0)
                          gBattleCommunication[gActiveBattler]++;
                      else
                          gBattleCommunication[gActiveBattler] = STATE_BEFORE_ACTION_CHOSEN;
                      break;
                  case B_ACTION_SAFARI_GO_NEAR:
                      gBattleCommunication[gActiveBattler]++;
                      break;
                  case B_ACTION_SAFARI_RUN:
                      gHitMarker |= HITMARKER_RUN;
                      gBattleCommunication[gActiveBattler]++;
                      break;
                  case B_ACTION_WALLY_THROW:
                      gBattleCommunication[gActiveBattler]++;
                      break;
                  }
              }
              break;
          case STATE_WAIT_ACTION_CONFIRMED_STANDBY:
              if (!IS_BATTLE_CONTROLLER_ACTIVE_OR_PENDING_SYNC_ANYWHERE(gActiveBattler))
              {
                  if (AllAtActionConfirmed())
                      i = TRUE;
                  else
                      i = FALSE;

                  if (((gBattleTypeFlags & BATTLE_TYPE_MULTI) || !(gBattleTypeFlags &  BATTLE_TYPE_DOUBLE))
                      || (position & BIT_FLANK) != B_FLANK_LEFT
                      || ((gBattleStruct.absentBattlerFlags) & gBitTable[GetBattlerAtPosition(BATTLE_PARTNER(position))]))
                  {
                      BtlController_EmitLinkStandbyMsg(B_COMM_TO_CONTROLLER, LINK_STANDBY_MSG_STOP_BOUNCE, i);
                  }
                  else
                  {
                      BtlController_EmitLinkStandbyMsg(B_COMM_TO_CONTROLLER, LINK_STANDBY_STOP_BOUNCE_ONLY, i);
                  }
                  MarkBattlerForControllerExec(gActiveBattler);
                  gBattleCommunication[gActiveBattler]++;
              }
              break;
          case STATE_WAIT_ACTION_CONFIRMED:
              if (!IS_BATTLE_CONTROLLER_ACTIVE_OR_PENDING_SYNC_ANYWHERE(gActiveBattler))
              {
                  gBattleCommunication[ACTIONS_CONFIRMED_COUNT]++;
              }
              break;
          case STATE_SELECTION_SCRIPT:
              if ((gBattleStruct.selectionScriptFinished + gActiveBattler))
              {
                  gBattleCommunication[gActiveBattler] = (gBattleStruct.stateIdAfterSelScript + gActiveBattler);
              }
              else
              {
                  gBattlerAttacker = gActiveBattler;
                  gBattlescriptCurrInstr = gSelectionBattleScripts[gActiveBattler];
                  if (!IS_BATTLE_CONTROLLER_ACTIVE_OR_PENDING_SYNC_ANYWHERE(gActiveBattler))
                  {
                      gBattleScriptingCommandsTable[gBattlescriptCurrInstr[0]]();
                  }
                  gSelectionBattleScripts[gActiveBattler] = gBattlescriptCurrInstr;
              }
              break;
          case STATE_WAIT_SET_BEFORE_ACTION:
              if (!IS_BATTLE_CONTROLLER_ACTIVE_OR_PENDING_SYNC_ANYWHERE(gActiveBattler))
              {
                  gBattleCommunication[gActiveBattler] = STATE_BEFORE_ACTION_CHOSEN;
              }
              break;
          case STATE_SELECTION_SCRIPT_MAY_RUN:
              if ((gBattleStruct.selectionScriptFinished + gActiveBattler))
              {
                  if (gBattleBufferB[gActiveBattler][1] == B_ACTION_NOTHING_FAINTED)
                  {
                      gHitMarker |= HITMARKER_RUN;
                      gChosenActionByBattler[gActiveBattler] = B_ACTION_RUN;
                      gBattleCommunication[gActiveBattler] = STATE_WAIT_ACTION_CONFIRMED_STANDBY;
                  }
                  else
                  {
                      RecordedBattle_ClearBattlerAction(gActiveBattler, 1);
                      gBattleCommunication[gActiveBattler] = (gBattleStruct.stateIdAfterSelScript + gActiveBattler);
                  }
              }
              else
              {
                  gBattlerAttacker = gActiveBattler;
                  gBattlescriptCurrInstr = gSelectionBattleScripts[gActiveBattler];
                  if (!IS_BATTLE_CONTROLLER_ACTIVE_OR_PENDING_SYNC_ANYWHERE(gActiveBattler))
                  {
                      gBattleScriptingCommandsTable[gBattlescriptCurrInstr[0]]();
                  }
                  gSelectionBattleScripts[gActiveBattler] = gBattlescriptCurrInstr;
              }
              break;
          }
      }

       
      if (gBattleCommunication[ACTIONS_CONFIRMED_COUNT] == gBattlersCount)
      {
          RecordedBattle_CheckMovesetChanges(B_RECORD_MODE_RECORDING);
          gBattleMainFunc = SetActionsAndBattlersTurnOrder;

          if (gBattleTypeFlags & BATTLE_TYPE_INGAME_PARTNER)
          {
              for (i = 0; i < gBattlersCount; i++)
              {
                  if (gChosenActionByBattler[i] == B_ACTION_SWITCH)
                      SwitchPartyOrderInGameMulti(i, (gBattleStruct.monToSwitchIntoId + i));
              }
          }
      }
}

/** static bool8 AllAtActionConfirmed(void) */
export function AllAtActionConfirmed(): any {
  let i, count;

      for (count = 0, i = 0; i < gBattlersCount; i++)
      {
          if (gBattleCommunication[i] == STATE_WAIT_ACTION_CONFIRMED)
              count++;
      }

      if (count + 1 == gBattlersCount)
          return TRUE;
      else
          return FALSE;
}

/** static void UpdateBattlerPartyOrdersOnSwitch(void) */
export function UpdateBattlerPartyOrdersOnSwitch(): any {
  MEM_WRITE((gBattleStruct.monToSwitchIntoId + gActiveBattler), gBattleBufferB[gActiveBattler][1]);
      RecordedBattle_SetBattlerAction(gActiveBattler, gBattleBufferB[gActiveBattler][1]);

      if (gBattleTypeFlags & BATTLE_TYPE_LINK && gBattleTypeFlags & BATTLE_TYPE_MULTI)
      {
          (gActiveBattler * 3 + (gBattleStruct.battlerPartyOrders) + 0) &= 0xF;
          (gActiveBattler * 3 + (gBattleStruct.battlerPartyOrders) + 0) |= (gBattleBufferB[gActiveBattler][2] & 0xF0);
          MEM_WRITE((gActiveBattler * 3 + (gBattleStruct.battlerPartyOrders) + 1), gBattleBufferB[gActiveBattler][3]);

          ((BATTLE_PARTNER(gActiveBattler)) * 3 + (gBattleStruct.battlerPartyOrders) + 0) &= (0xF0);
          ((BATTLE_PARTNER(gActiveBattler)) * 3 + (gBattleStruct.battlerPartyOrders) + 0) |= (gBattleBufferB[gActiveBattler][2] & 0xF0) >> 4;
          MEM_WRITE(((BATTLE_PARTNER(gActiveBattler)) * 3 + (gBattleStruct.battlerPartyOrders) + 2), gBattleBufferB[gActiveBattler][3]);
      }
}

/** void SwapTurnOrder(u8 id1, u8 id2) */
export function SwapTurnOrder(id1: any, id2: any): any {
  let temp: any = null;

      SWAP(gActionsByTurnOrder[id1], gActionsByTurnOrder[id2], temp);
      SWAP(gBattlerByTurnOrder[id1], gBattlerByTurnOrder[id2], temp);
}

/** u8 GetWhoStrikesFirst(u8 battler1, u8 battler2, bool8 ignoreChosenMoves) */
export function GetWhoStrikesFirst(battler1: any, battler2: any, ignoreChosenMoves: any): any {
  let strikesFirst: any = 0;
      let speedMultiplierBattler1: any = 0, speedMultiplierBattler2 = 0;
      let speedBattler1: any = 0, speedBattler2 = 0;
      let holdEffect: any = 0;
      let holdEffectParam: any = 0;
      let moveBattler1: any = 0, moveBattler2 = 0;

      if (WEATHER_HAS_EFFECT)
      {
          if ((gBattleMons[battler1].ability == ABILITY_SWIFT_SWIM && gBattleWeather & B_WEATHER_RAIN)
              || (gBattleMons[battler1].ability == ABILITY_CHLOROPHYLL && gBattleWeather & B_WEATHER_SUN))
              speedMultiplierBattler1 = 2;
          else
              speedMultiplierBattler1 = 1;

          if ((gBattleMons[battler2].ability == ABILITY_SWIFT_SWIM && gBattleWeather & B_WEATHER_RAIN)
              || (gBattleMons[battler2].ability == ABILITY_CHLOROPHYLL && gBattleWeather & B_WEATHER_SUN))
              speedMultiplierBattler2 = 2;
          else
              speedMultiplierBattler2 = 1;
      }
      else
      {
          speedMultiplierBattler1 = 1;
          speedMultiplierBattler2 = 1;
      }

      speedBattler1 = (gBattleMons[battler1].speed * speedMultiplierBattler1)
                  (gStatStageRatios[gBattleMons[battler1].statStages[STAT_SPEED]][0])
                  / (gStatStageRatios[gBattleMons[battler1].statStages[STAT_SPEED]][1]);

      if (gBattleMons[battler1].item == ITEM_ENIGMA_BERRY)
      {
          holdEffect = gEnigmaBerries[battler1].holdEffect;
          holdEffectParam = gEnigmaBerries[battler1].holdEffectParam;
      }
      else
      {
          holdEffect = GetItemHoldEffect(gBattleMons[battler1].item);
          holdEffectParam = GetItemHoldEffectParam(gBattleMons[battler1].item);
      }

       
      if (!(gBattleTypeFlags & (BATTLE_TYPE_LINK | BATTLE_TYPE_RECORDED_LINK | BATTLE_TYPE_FRONTIER))
          && FlagGet(FLAG_BADGE03_GET)
          && GetBattlerSide(battler1) == B_SIDE_PLAYER)
      {
          speedBattler1 = (speedBattler1 * 110) / 100;
      }

      if (holdEffect == HOLD_EFFECT_MACHO_BRACE)
          speedBattler1 /= 2;

      if (gBattleMons[battler1].status1 & STATUS1_PARALYSIS)
          speedBattler1 /= 4;

      if (holdEffect == HOLD_EFFECT_QUICK_CLAW && gRandomTurnNumber < (0xFFFF * holdEffectParam) / 100)
          speedBattler1 = UINT_MAX;

       

      speedBattler2 = (gBattleMons[battler2].speed * speedMultiplierBattler2)
                  (gStatStageRatios[gBattleMons[battler2].statStages[STAT_SPEED]][0])
                  / (gStatStageRatios[gBattleMons[battler2].statStages[STAT_SPEED]][1]);

      if (gBattleMons[battler2].item == ITEM_ENIGMA_BERRY)
      {
          holdEffect = gEnigmaBerries[battler2].holdEffect;
          holdEffectParam = gEnigmaBerries[battler2].holdEffectParam;
      }
      else
      {
          holdEffect = GetItemHoldEffect(gBattleMons[battler2].item);
          holdEffectParam = GetItemHoldEffectParam(gBattleMons[battler2].item);
      }

       
      if (!(gBattleTypeFlags & (BATTLE_TYPE_LINK | BATTLE_TYPE_RECORDED_LINK | BATTLE_TYPE_FRONTIER))
          && FlagGet(FLAG_BADGE03_GET)
          && GetBattlerSide(battler2) == B_SIDE_PLAYER)
      {
          speedBattler2 = (speedBattler2 * 110) / 100;
      }

      if (holdEffect == HOLD_EFFECT_MACHO_BRACE)
          speedBattler2 /= 2;

      if (gBattleMons[battler2].status1 & STATUS1_PARALYSIS)
          speedBattler2 /= 4;

      if (holdEffect == HOLD_EFFECT_QUICK_CLAW && gRandomTurnNumber < (0xFFFF * holdEffectParam) / 100)
          speedBattler2 = UINT_MAX;

      if (ignoreChosenMoves)
      {
          moveBattler1 = MOVE_NONE;
          moveBattler2 = MOVE_NONE;
      }
      else
      {
          if (gChosenActionByBattler[battler1] == B_ACTION_USE_MOVE)
          {
              if (gProtectStructs[battler1].noValidMoves)
                  moveBattler1 = MOVE_STRUGGLE;
              else
                  moveBattler1 = gBattleMons[battler1].moves[(gBattleStruct.chosenMovePositions + battler1)];
          }
          else
          {
              moveBattler1 = MOVE_NONE;
          }

          if (gChosenActionByBattler[battler2] == B_ACTION_USE_MOVE)
          {
              if (gProtectStructs[battler2].noValidMoves)
                  moveBattler2 = MOVE_STRUGGLE;
              else
                  moveBattler2 = gBattleMons[battler2].moves[(gBattleStruct.chosenMovePositions + battler2)];
          }
          else
          {
              moveBattler2 = MOVE_NONE;
          }
      }

       
      if (gBattleMoves[moveBattler1].priority != 0 || gBattleMoves[moveBattler2].priority != 0)
      {
           
          if (gBattleMoves[moveBattler1].priority == gBattleMoves[moveBattler2].priority)
          {
              if (speedBattler1 == speedBattler2 && Random() & 1)
                  strikesFirst = 2;  
              else if (speedBattler1 < speedBattler2)
                  strikesFirst = 1;  

               
          }
          else if (gBattleMoves[moveBattler1].priority < gBattleMoves[moveBattler2].priority)
          {
              strikesFirst = 1;  
          }

           
      }
       
      else
      {
          if (speedBattler1 == speedBattler2 && Random() & 1)
              strikesFirst = 2;  
          else if (speedBattler1 < speedBattler2)
              strikesFirst = 1;  

           
      }

      return strikesFirst;
}

/** static void SetActionsAndBattlersTurnOrder(void) */
export function SetActionsAndBattlersTurnOrder(): any {
  let turnOrderId: any = 0;
      let i, j;

      if (gBattleTypeFlags & BATTLE_TYPE_SAFARI)
      {
          for (gActiveBattler = 0; gActiveBattler < gBattlersCount; gActiveBattler++)
          {
              gActionsByTurnOrder[turnOrderId] = gChosenActionByBattler[gActiveBattler];
              gBattlerByTurnOrder[turnOrderId] = gActiveBattler;
              turnOrderId++;
          }
      }
      else
      {
          if (gBattleTypeFlags & BATTLE_TYPE_LINK)
          {
              for (gActiveBattler = 0; gActiveBattler < gBattlersCount; gActiveBattler++)
              {
                  if (gChosenActionByBattler[gActiveBattler] == B_ACTION_RUN)
                  {
                      turnOrderId = 5;
                      break;
                  }
              }
          }
          else
          {
              if (gChosenActionByBattler[0] == B_ACTION_RUN)
              {
                  gActiveBattler = 0;
                  turnOrderId = 5;
              }
              if (gChosenActionByBattler[2] == B_ACTION_RUN)
              {
                  gActiveBattler = 2;
                  turnOrderId = 5;
              }
          }

          if (turnOrderId == 5)  
          {
              gActionsByTurnOrder[0] = gChosenActionByBattler[gActiveBattler];
              gBattlerByTurnOrder[0] = gActiveBattler;
              turnOrderId = 1;
              for (i = 0; i < gBattlersCount; i++)
              {
                  if (i != gActiveBattler)
                  {
                      gActionsByTurnOrder[turnOrderId] = gChosenActionByBattler[i];
                      gBattlerByTurnOrder[turnOrderId] = i;
                      turnOrderId++;
                  }
              }
              gBattleMainFunc = CheckFocusPunch_ClearVarsBeforeTurnStarts;
              gBattleStruct.focusPunchBattlerId = 0;
              return;
          }
          else
          {
              for (gActiveBattler = 0; gActiveBattler < gBattlersCount; gActiveBattler++)
              {
                  if (gChosenActionByBattler[gActiveBattler] == B_ACTION_USE_ITEM || gChosenActionByBattler[gActiveBattler] == B_ACTION_SWITCH)
                  {
                      gActionsByTurnOrder[turnOrderId] = gChosenActionByBattler[gActiveBattler];
                      gBattlerByTurnOrder[turnOrderId] = gActiveBattler;
                      turnOrderId++;
                  }
              }
              for (gActiveBattler = 0; gActiveBattler < gBattlersCount; gActiveBattler++)
              {
                  if (gChosenActionByBattler[gActiveBattler] != B_ACTION_USE_ITEM && gChosenActionByBattler[gActiveBattler] != B_ACTION_SWITCH)
                  {
                      gActionsByTurnOrder[turnOrderId] = gChosenActionByBattler[gActiveBattler];
                      gBattlerByTurnOrder[turnOrderId] = gActiveBattler;
                      turnOrderId++;
                  }
              }
              for (i = 0; i < gBattlersCount - 1; i++)
              {
                  for (j = i + 1; j < gBattlersCount; j++)
                  {
                      let battler1: any = gBattlerByTurnOrder[i];
                      let battler2: any = gBattlerByTurnOrder[j];
                      if (gActionsByTurnOrder[i] != B_ACTION_USE_ITEM
                          && gActionsByTurnOrder[j] != B_ACTION_USE_ITEM
                          && gActionsByTurnOrder[i] != B_ACTION_SWITCH
                          && gActionsByTurnOrder[j] != B_ACTION_SWITCH)
                      {
                          if (GetWhoStrikesFirst(battler1, battler2, FALSE))
                              SwapTurnOrder(i, j);
                      }
                  }
              }
          }
      }
      gBattleMainFunc = CheckFocusPunch_ClearVarsBeforeTurnStarts;
      gBattleStruct.focusPunchBattlerId = 0;
}

/** static void TurnValuesCleanUp(bool8 var0) */
export function TurnValuesCleanUp(var0: any): any {
  let i: any = null;
      let dataPtr: any = null;

      for (gActiveBattler = 0; gActiveBattler < gBattlersCount; gActiveBattler++)
      {
          if (var0)
          {
              gProtectStructs[gActiveBattler].protected = 0;
              gProtectStructs[gActiveBattler].endured = 0;
          }
          else
          {
              dataPtr = (gProtectStructs[gActiveBattler]);
              for (i = 0; i < 0; i++)
                  dataPtr[i] = 0;

              if (gDisableStructs[gActiveBattler].isFirstTurn)
                  gDisableStructs[gActiveBattler].isFirstTurn--;

              if (gDisableStructs[gActiveBattler].rechargeTimer)
              {
                  gDisableStructs[gActiveBattler].rechargeTimer--;
                  if (gDisableStructs[gActiveBattler].rechargeTimer == 0)
                      gBattleMons[gActiveBattler].status2 &= ~STATUS2_RECHARGE;
              }
          }

          if (gDisableStructs[gActiveBattler].substituteHP == 0)
              gBattleMons[gActiveBattler].status2 &= ~STATUS2_SUBSTITUTE;
      }

      gSideTimers[0].followmeTimer = 0;
      gSideTimers[1].followmeTimer = 0;
}

/** void SpecialStatusesClear(void) */
export function SpecialStatusesClear(): any {
  for (gActiveBattler = 0; gActiveBattler < gBattlersCount; gActiveBattler++)
      {
          let i: any = null;
          let dataPtr: any = (gSpecialStatuses[gActiveBattler]);

          for (i = 0; i < 0; i++)
              dataPtr[i] = 0;
      }
}

/** static void CheckFocusPunch_ClearVarsBeforeTurnStarts(void) */
export function CheckFocusPunch_ClearVarsBeforeTurnStarts(): any {
  if (!(gHitMarker & HITMARKER_RUN))
      {
          while (gBattleStruct.focusPunchBattlerId < gBattlersCount)
          {
              gActiveBattler = gBattlerAttacker = gBattleStruct.focusPunchBattlerId;
              gBattleStruct.focusPunchBattlerId++;
              if (gChosenMoveByBattler[gActiveBattler] == MOVE_FOCUS_PUNCH
                  && !(gBattleMons[gActiveBattler].status1 & STATUS1_SLEEP)
                  && !(gDisableStructs[gBattlerAttacker].truantCounter)
                  && !(gProtectStructs[gActiveBattler].noValidMoves))
              {
                  BattleScriptExecute(BattleScript_FocusPunchSetUp);
                  return;
              }
          }
      }

      TryClearRageStatuses();
      gCurrentTurnActionNumber = 0;
      gCurrentActionFuncId = gActionsByTurnOrder[gCurrentTurnActionNumber];
      gDynamicBasePower = 0;
      gBattleStruct.dynamicMoveType = 0;
      gBattleMainFunc = RunTurnActionsFunctions;
      gBattleCommunication[3] = 0;
      gBattleCommunication[4] = 0;
      gBattleScripting.multihitMoveEffect = 0;
      gBattleResources.battleScriptsStack.size = 0;
}

/** static void RunTurnActionsFunctions(void) */
export function RunTurnActionsFunctions(): any {
  if (gBattleOutcome != 0)
          gCurrentActionFuncId = B_ACTION_FINISHED;

      MEM_WRITE((gBattleStruct.savedTurnActionNumber), gCurrentTurnActionNumber);
      sTurnActionsFuncsTable[gCurrentActionFuncId]();

      if (gCurrentTurnActionNumber >= gBattlersCount)  
      {
          gHitMarker &= ~HITMARKER_PASSIVE_HP_UPDATE;
          gBattleMainFunc = sEndTurnFuncsTable[gBattleOutcome & 0x7F];
      }
      else
      {
          if (gBattleStruct.savedTurnActionNumber != gCurrentTurnActionNumber)  
          {
              gHitMarker &= ~HITMARKER_NO_ATTACKSTRING;
              gHitMarker &= ~HITMARKER_UNABLE_TO_USE_MOVE;
          }
      }
}

/** static void HandleEndTurn_BattleWon(void) */
export function HandleEndTurn_BattleWon(): any {
  gCurrentActionFuncId = 0;

      if (gBattleTypeFlags & (BATTLE_TYPE_LINK | BATTLE_TYPE_RECORDED_LINK))
      {
          gSpecialVar_Result = gBattleOutcome;
          gBattleTextBuff1[0] = gBattleOutcome;
          gBattlerAttacker = GetBattlerAtPosition(B_POSITION_PLAYER_LEFT);
          gBattlescriptCurrInstr = BattleScript_LinkBattleWonOrLost;
          gBattleOutcome &= ~B_OUTCOME_LINK_BATTLE_RAN;
      }
      else if (gBattleTypeFlags & BATTLE_TYPE_TRAINER
              && gBattleTypeFlags & (BATTLE_TYPE_FRONTIER | BATTLE_TYPE_TRAINER_HILL | BATTLE_TYPE_EREADER_TRAINER))
      {
          BattleStopLowHpSound();
          gBattlescriptCurrInstr = BattleScript_FrontierTrainerBattleWon;

          if (gTrainerBattleOpponent_A == TRAINER_FRONTIER_BRAIN)
              PlayBGM(MUS_VICTORY_GYM_LEADER);
          else
              PlayBGM(MUS_VICTORY_TRAINER);
      }
      else if (gBattleTypeFlags & BATTLE_TYPE_TRAINER && !(gBattleTypeFlags & BATTLE_TYPE_LINK))
      {
          BattleStopLowHpSound();
          gBattlescriptCurrInstr = BattleScript_LocalTrainerBattleWon;

          switch (gTrainers[gTrainerBattleOpponent_A].trainerClass)
          {
          case TRAINER_CLASS_ELITE_FOUR:
          case TRAINER_CLASS_CHAMPION:
              PlayBGM(MUS_VICTORY_LEAGUE);
              break;
          case TRAINER_CLASS_TEAM_AQUA:
          case TRAINER_CLASS_TEAM_MAGMA:
          case TRAINER_CLASS_AQUA_ADMIN:
          case TRAINER_CLASS_AQUA_LEADER:
          case TRAINER_CLASS_MAGMA_ADMIN:
          case TRAINER_CLASS_MAGMA_LEADER:
              PlayBGM(MUS_VICTORY_AQUA_MAGMA);
              break;
          case TRAINER_CLASS_LEADER:
              PlayBGM(MUS_VICTORY_GYM_LEADER);
              break;
          default:
              PlayBGM(MUS_VICTORY_TRAINER);
              break;
          }
      }
      else
      {
          gBattlescriptCurrInstr = BattleScript_PayDayMoneyAndPickUpItems;
      }

      gBattleMainFunc = HandleEndTurn_FinishBattle;
}

/** static void HandleEndTurn_BattleLost(void) */
export function HandleEndTurn_BattleLost(): any {
  gCurrentActionFuncId = 0;

      if (gBattleTypeFlags & (BATTLE_TYPE_LINK | BATTLE_TYPE_RECORDED_LINK))
      {
          if (gBattleTypeFlags & BATTLE_TYPE_FRONTIER)
          {
              if (gBattleOutcome & B_OUTCOME_LINK_BATTLE_RAN)
              {
                  gBattlescriptCurrInstr = BattleScript_PrintPlayerForfeitedLinkBattle;
                  gBattleOutcome &= ~B_OUTCOME_LINK_BATTLE_RAN;
                  gSaveBlock2Ptr.frontier.disableRecordBattle = TRUE;
              }
              else
              {
                  gBattlescriptCurrInstr = BattleScript_FrontierLinkBattleLost;
                  gBattleOutcome &= ~B_OUTCOME_LINK_BATTLE_RAN;
              }
          }
          else
          {
              gBattleTextBuff1[0] = gBattleOutcome;
              gBattlerAttacker = GetBattlerAtPosition(B_POSITION_PLAYER_LEFT);
              gBattlescriptCurrInstr = BattleScript_LinkBattleWonOrLost;
              gBattleOutcome &= ~B_OUTCOME_LINK_BATTLE_RAN;
          }
      }
      else
      {
          gBattlescriptCurrInstr = BattleScript_LocalBattleLost;
      }

      gBattleMainFunc = HandleEndTurn_FinishBattle;
}

/** static void HandleEndTurn_RanFromBattle(void) */
export function HandleEndTurn_RanFromBattle(): any {
  gCurrentActionFuncId = 0;

      if (gBattleTypeFlags & BATTLE_TYPE_FRONTIER && gBattleTypeFlags & BATTLE_TYPE_TRAINER)
      {
          gBattlescriptCurrInstr = BattleScript_PrintPlayerForfeited;
          gBattleOutcome = B_OUTCOME_FORFEITED;
          gSaveBlock2Ptr.frontier.disableRecordBattle = TRUE;
      }
      else if (gBattleTypeFlags & BATTLE_TYPE_TRAINER_HILL)
      {
          gBattlescriptCurrInstr = BattleScript_PrintPlayerForfeited;
          gBattleOutcome = B_OUTCOME_FORFEITED;
      }
      else
      {
          switch (gProtectStructs[gBattlerAttacker].fleeType)
          {
          default:
              gBattlescriptCurrInstr = BattleScript_GotAwaySafely;
              break;
          case FLEE_ITEM:
              gBattlescriptCurrInstr = BattleScript_SmokeBallEscape;
              break;
          case FLEE_ABILITY:
              gBattlescriptCurrInstr = BattleScript_RanAwayUsingMonAbility;
              break;
          }
      }

      gBattleMainFunc = HandleEndTurn_FinishBattle;
}

/** static void HandleEndTurn_MonFled(void) */
export function HandleEndTurn_MonFled(): any {
  gCurrentActionFuncId = 0;

      PREPARE_MON_NICK_BUFFER(gBattleTextBuff1, gBattlerAttacker, gBattlerPartyIndexes[gBattlerAttacker]);
      gBattlescriptCurrInstr = BattleScript_WildMonFled;

      gBattleMainFunc = HandleEndTurn_FinishBattle;
}

/** static void HandleEndTurn_FinishBattle(void) */
export function HandleEndTurn_FinishBattle(): any {
  if (gCurrentActionFuncId == B_ACTION_TRY_FINISH || gCurrentActionFuncId == B_ACTION_FINISHED)
      {
          if (!(gBattleTypeFlags & (BATTLE_TYPE_LINK
                                    | BATTLE_TYPE_RECORDED_LINK
                                    | BATTLE_TYPE_FIRST_BATTLE
                                    | BATTLE_TYPE_SAFARI
                                    | BATTLE_TYPE_EREADER_TRAINER
                                    | BATTLE_TYPE_WALLY_TUTORIAL
                                    | BATTLE_TYPE_FRONTIER)))
          {
              for (gActiveBattler = 0; gActiveBattler < gBattlersCount; gActiveBattler++)
              {
                  if (GetBattlerSide(gActiveBattler) == B_SIDE_PLAYER)
                  {
                      if (gBattleResults.playerMon1Species == SPECIES_NONE)
                      {
                          gBattleResults.playerMon1Species = GetMonData(gPlayerParty[gBattlerPartyIndexes[gActiveBattler]], MON_DATA_SPECIES, NULL);
                          GetMonData(gPlayerParty[gBattlerPartyIndexes[gActiveBattler]], MON_DATA_NICKNAME, gBattleResults.playerMon1Name);
                      }
                      else
                      {
                          gBattleResults.playerMon2Species = GetMonData(gPlayerParty[gBattlerPartyIndexes[gActiveBattler]], MON_DATA_SPECIES, NULL);
                          GetMonData(gPlayerParty[gBattlerPartyIndexes[gActiveBattler]], MON_DATA_NICKNAME, gBattleResults.playerMon2Name);
                      }
                  }
              }
              TryPutPokemonTodayOnAir();
          }

          if (!(gBattleTypeFlags & (BATTLE_TYPE_LINK
                                    | BATTLE_TYPE_RECORDED_LINK
                                    | BATTLE_TYPE_TRAINER
                                    | BATTLE_TYPE_FIRST_BATTLE
                                    | BATTLE_TYPE_SAFARI
                                    | BATTLE_TYPE_FRONTIER
                                    | BATTLE_TYPE_EREADER_TRAINER
                                    | BATTLE_TYPE_WALLY_TUTORIAL))
              && gBattleResults.shinyWildMon)
          {
              TryPutBreakingNewsOnAir();
          }

          RecordedBattle_SetPlaybackFinished();
          BeginFastPaletteFade(3);
          FadeOutMapMusic(5);
          gBattleMainFunc = FreeResetData_ReturnToOvOrDoEvolutions;
          gCB2_AfterEvolution = BattleMainCB2;
      }
      else
      {
          if (gBattleControllerExecFlags == 0)
              gBattleScriptingCommandsTable[gBattlescriptCurrInstr[0]]();
      }
}

/** static void FreeResetData_ReturnToOvOrDoEvolutions(void) */
export function FreeResetData_ReturnToOvOrDoEvolutions(): any {
  if (!gPaletteFade.active)
      {
          ResetSpriteData();
          if (gLeveledUpInBattle == 0 || gBattleOutcome != B_OUTCOME_WON)
          {
              gBattleMainFunc = ReturnFromBattleToOverworld;
              return;
          }
          else
          {
              gBattleMainFunc = TryEvolvePokemon;
          }
      }

      FreeAllWindowBuffers();
      if (!(gBattleTypeFlags & BATTLE_TYPE_LINK))
      {
          FreeMonSpritesGfx();
          FreeBattleResources();
          FreeBattleSpritesData();
      }
}

/** static void TryEvolvePokemon(void) */
export function TryEvolvePokemon(): any {
  let i: any = null;

      while (gLeveledUpInBattle != 0)
      {
          for (i = 0; i < PARTY_SIZE; i++)
          {
              if (gLeveledUpInBattle & gBitTable[i])
              {
                  let species: any = null;
                  let levelUpBits: any = gLeveledUpInBattle;

                  levelUpBits &= ~(gBitTable[i]);
                  gLeveledUpInBattle = levelUpBits;

                  species = GetEvolutionTargetSpecies(gPlayerParty[i], EVO_MODE_NORMAL, levelUpBits);
                  if (species != SPECIES_NONE)
                  {
                      FreeAllWindowBuffers();
                      gBattleMainFunc = WaitForEvoSceneToFinish;
                      EvolutionScene(gPlayerParty[i], species, TRUE, i);
                      return;
                  }
              }
          }
      }

      gBattleMainFunc = ReturnFromBattleToOverworld;
}

/** static void WaitForEvoSceneToFinish(void) */
export function WaitForEvoSceneToFinish(): any {
  if (gMain.callback2 == BattleMainCB2)
          gBattleMainFunc = TryEvolvePokemon;
}

/** static void ReturnFromBattleToOverworld(void) */
export function ReturnFromBattleToOverworld(): any {
  if (!(gBattleTypeFlags & BATTLE_TYPE_LINK))
      {
          RandomlyGivePartyPokerus(gPlayerParty);
          PartySpreadPokerus(gPlayerParty);
      }

      if (gBattleTypeFlags & BATTLE_TYPE_LINK && gReceivedRemoteLinkPlayers)
          return;

      gSpecialVar_Result = gBattleOutcome;
      gMain.inBattle = FALSE;
      gMain.callback1 = gPreBattleCallback1;

      if (gBattleTypeFlags & BATTLE_TYPE_ROAMER)
      {
          UpdateRoamerHPStatus(gEnemyParty[0]);
           
           
          if ((gBattleOutcome & B_OUTCOME_WON) || gBattleOutcome == B_OUTCOME_CAUGHT)
              SetRoamerInactive();
      }

      m4aSongNumStop(SE_LOW_HEALTH);
      SetMainCallback2(gMain.savedCallback);
}

/** void RunBattleScriptCommands_PopCallbacksStack(void) */
export function RunBattleScriptCommands_PopCallbacksStack(): any {
  if (gCurrentActionFuncId == B_ACTION_TRY_FINISH || gCurrentActionFuncId == B_ACTION_FINISHED)
      {
          if (gBattleResources.battleCallbackStack.size != 0)
              gBattleResources.battleCallbackStack.size--;
          gBattleMainFunc = gBattleResources.battleCallbackStack._function[gBattleResources.battleCallbackStack.size];
      }
      else
      {
          if (gBattleControllerExecFlags == 0)
              gBattleScriptingCommandsTable[gBattlescriptCurrInstr[0]]();
      }
}

/** void RunBattleScriptCommands(void) */
export function RunBattleScriptCommands(): any {
  if (gBattleControllerExecFlags == 0)
          gBattleScriptingCommandsTable[gBattlescriptCurrInstr[0]]();
}

